window.COURSE = {"version":1,"updated":"2026-10-30","lessons":[{"id":1,"phase":1,"title":"卖出的钱，都是收入？","topic":"GMV vs Revenue","core":"GMV描述交易规模，Revenue描述按明确口径确认的收入，利润还要扣成本。先问“谁的收入、包含什么、哪段时间”，再比较数字。","example":"假设：平台促成100单，每单50元，GMV为5,000元。若平台仅按10%收佣金，其佣金收入为500元。卖家则按自己的销售与收入确认口径计算。取消、退款、税费是否计入GMV，须先查报告定义。","takeaway":"平台的交易额不等于平台自己的收入。此例平台收入为佣金10,000×10%=1,000元；商品卖家的收入要另算。","task":"写出GMV与Revenue定义、差异和1个数字例子。","kind":"新知","minutes":"15–20","fields":["用自己的话说明GMV和收入的区别","写一个数字例子（可以用假设）"],"quizIds":["1","1b","extra1"],"sourceIds":["shopify-sales","ifrs-principal-agent"],"extra":[{"title":"成交额、收入和到账是三回事","core":"先问这是谁的账、在什么时间、按什么口径。自营商家销售商品与平台代为撮合，确认收入的方式可能不同；卖出商品也不代表款项已经到账。以下都是简化假设。"}]},{"id":2,"phase":1,"title":"一件商品的成本，从哪里开始？","topic":"COGS","core":"COGS是已售商品对应的成本。采购、包装和入库相关费用的归集要有一致口径。广告费要另列；已计入COGS的头程不能再扣一次。","example":"简化练习：商品采购10元、包装1.2元、配件0.8元，共12元。若运费等按企业政策计入存货成本，销售时对应转入COGS。经营表可另拆落地费用，但已经计入的项目不能重复扣减。","takeaway":"重复计费会低估利润。先说明每个成本字段包含哪些项目，再进行相加。","task":"列出一个SKU的COGS组成，并说明什么不属于COGS。","kind":"新知","minutes":"15–20","fields":["一个商品的成本组成","哪些项目已包含，哪些仍需核对？"],"quizIds":["2","1"],"sourceIds":["shopify-profit","ifrs-inventory"]},{"id":3,"phase":1,"title":"毛利高，就一定赚钱吗？","topic":"Gross Profit / Gross Margin","core":"毛利=净销售收入−已售商品成本；毛利率=毛利÷净销售收入。它是利润的一层，不能代替扣除营销等费用后的结果。","example":"Gross Profit=Revenue-COGS；Gross Margin=Gross Profit/Revenue。题1：售价$50、COGS $15→毛利$35、毛利率70%。题2：售价$80、COGS $36→毛利$44、毛利率55%。结论：销售额高不代表毛利率高。","takeaway":"毛利为60元，毛利率为60÷100=60%。60÷40是相对成本的加价比例，口径不同。","task":"写出毛利/毛利率公式并完成2道计算。","kind":"新知","minutes":"15–20","fields":["写一次毛利与毛利率计算","毛利之外还需要扣哪些费用？"],"quizIds":["3","1"],"sourceIds":["shopify-profit"]},{"id":4,"phase":1,"title":"给一个商品算清第一层利润","topic":"SKU毛利练习","core":"把收入、成本与期间写在一起。先算对，再说明这个结果还没包含哪些费用。缺数据时可以用明确标注的假设练习。","example":"（假设数据）：售价$49.99，COGS $12。毛利=$37.99；毛利率=76.0%。经营判断：毛利空间看起来高，但这只是第一层利润，后面还要扣头程、支付、履约、广告、退款后才能判断是否真赚钱。","takeaway":"80−36=44元；55%是毛利率。金额和比例不要混写。","task":"选1个SKU，写出售价、成本、毛利和一句经营判断。","kind":"新知","minutes":"15–20","fields":["我的理解 / 计算或选择","依据 / 假设 / 下一步"],"quizIds":["4","3"],"sourceIds":["shopify-profit","ifrs-inventory"]},{"id":5,"phase":1,"title":"不看笔记，把概念说出来","topic":"术语回忆","core":"主动回忆时先遮住答案。用自己的语言说明GMV、收入、成本和毛利，再用一个数字例子检查，而不只辨认英文。","example":"先试着解释：GMV看交易规模；收入看确认口径；COGS是已售商品对应成本；毛利是收入减COGS；净利润还需考虑其他费用。多说一句“这几个数字为什么不能混用”。","takeaway":"确认收入、收到现金和最终利润是不同概念。一个订单可以产生收入，却仍有成本和待收款。","task":"闭卷写出至少5个术语的大白话解释。","kind":"复习","minutes":"10–15","fields":["我的理解 / 计算或选择","依据 / 假设 / 下一步"],"quizIds":["5","2"],"sourceIds":["shopify-sales","ifrs-inventory","ifrs-principal-agent"]},{"id":6,"phase":1,"title":"搭起一张利润地图","topic":"P&L骨架","core":"把业务拆成收入、商品成本、其他可变费用、营销费和固定费用。单笔贡献利润帮助判断增量订单，整体净利润还要看固定费用。","example":"收入：售价/折后净收入；商品与入仓成本：COGS、包装、头程、关税、入仓；订单可变费：支付费、平台费、佣金、履约、尾程、退款预留；营销：CAC；结果：贡献利润、贡献毛利率、Break-even CAC/ROAS。","takeaway":"办公、薪资、订阅等固定或期间费用仍可能让整体亏损。订单贡献和公司净利润的边界不同。","task":"把P&L模型里的项目分成收入、商品成本、可变费用、营销费用、利润结果。","kind":"实践","minutes":"20–30","fields":["我的理解 / 计算或选择","依据 / 假设 / 下一步"],"quizIds":["6","3"],"sourceIds":["shopify-profit"]},{"id":7,"phase":1,"title":"第一周：我能解释什么了？","topic":"第1周复盘","core":"回顾一周时，找到一个已能解释的问题、一个仍不确定的数字、一个下一步动作。复盘要留下改变，而不是罗列看过的内容。","example":"本周我确认“销量≠利润”。一个SKU即使GMV很高，只要COGS、履约、平台费、退款、CAC叠加后超过净收入，就会越卖越亏。下周我要补齐Landed Cost和履约费用，因为目前最大盲区不在销售额，而在完整成本。","takeaway":"具体缺口、可执行动作和时间，让复盘能转为行动。阅读数量不能直接证明理解。","task":"完成第1周复盘：回答“卖得多为什么仍可能亏”。","kind":"复习","minutes":"10–15","fields":["这次学会了什么？留下了什么？","还没弄懂什么？下一步只做哪件事？"],"quizIds":["7","6"],"sourceIds":[]},{"id":8,"phase":1,"title":"货到仓库，真正花了多少钱？","topic":"Landed Cost","core":"Landed Cost是把货送达约定地点的完整落地成本。明确地点、数量与包含项；摊分采购、包装、头程、关税与入库，避免漏项或重复。","example":"假设采购12、包装1、头程2、关税1、入库1，落地成本为17。先确认采购报价是否已含包装和运费。不同币种先按注明日期的汇率换算，保留原始金额。","takeaway":"五项相加为17。计算前需确认报价是否已经包含其中部分项目。","task":"列出1个SKU的Landed Cost组成并算一次。","kind":"新知","minutes":"15–20","fields":["我的理解 / 计算或选择","依据 / 假设 / 下一步"],"quizIds":["8","2","extra2"],"sourceIds":["ifrs-inventory"],"extra":[{"title":"每项成本只扣一次","core":"成本表先写清包含什么。若到仓成本已含采购价、头程和关税，计算利润时减这项合计即可；不能再把采购价重复减一次。多件商品订单还要按件数换算。"}]},{"id":9,"phase":1,"title":"平台费和支付费，逐项认领","topic":"平台费 / 支付费","core":"不同渠道的费用结构不同。按市场、类目、尺寸和服务读取当前官方费用；比例费、固定费和退款后处理规则要分清。","example":"Shopify常见是支付处理费+应用/履约等自有成本；Amazon则还要考虑Referral Fee、FBA等平台/履约费用。核心不是背固定费率，而是所有“每成交一单就产生的费用”都必须进入单位经济模型。","takeaway":"固定费率不是通用事实。把费率来源和核对日期写入模型，变化后再更新。","task":"比较Shopify支付费与Amazon平台费用的本质区别。","kind":"新知","minutes":"15–20","fields":["我的理解 / 计算或选择","依据 / 假设 / 下一步"],"quizIds":["9","8"],"sourceIds":["amazon-pricing"]},{"id":10,"phase":1,"title":"订单出了仓，成本还没结束","topic":"履约 / 尾程","core":"履约包括拣货、打包、包材、出库与尾程，另有尺寸、偏远地区和逆向物流等可能费用。按实际计费单位摊到订单。","example":"订单产生→仓库拣货Pick→打包Pack→包材→出库处理→Last-mile尾程配送→可能的偏远/超重附加费→退货逆向物流。经营上要把这些费用摊到每单，而不是只看头程。","takeaway":"“履约”这个词不保证报价包含全链路。要问清服务边界、计费重量和附加费。","task":"写出一单从仓库到客户的履约费用链。","kind":"新知","minutes":"15–20","fields":["我的理解 / 计算或选择","依据 / 假设 / 下一步"],"quizIds":["10","9"],"sourceIds":[]},{"id":11,"phase":1,"title":"退一单，到底损失多少？","topic":"退款与损耗","core":"退款会减少收入，也可能带来回收商品、逆向运费和不可退手续费。订单退款率与金额退款率分开；已扣的退款不要再全额预留。","example":"假设100笔订单中5笔退款，订单退款率5%。若总销售额5,000元、实际退款400元，金额退款率为8%。已从收入扣除这400元后，不能再把同笔退款全额作为费用扣一次。","takeaway":"同一笔损失只能计一次。未来退款预留与已发生退款应分开核算。","task":"用5%和10%退款率做一次利润预留。","kind":"新知","minutes":"15–20","fields":["我的理解 / 计算或选择","依据 / 假设 / 下一步"],"quizIds":["11","3"],"sourceIds":["shopify-sales"]},{"id":12,"phase":1,"title":"复习：成本数字要能对上","topic":"主动回忆","core":"同一口径和同一期间是比较的前提。退款订单占比不等于退款金额占比；货值很大的少数退单可能带来较大损失。","example":"同样5%的订单退款率，可能来自低价订单，也可能来自高价订单。判断利润要看退款金额、可回收货值、逆向运费与不可退费用，并说明是否已包含在净收入里。","takeaway":"订单退款率是5%，但不同订单金额不同。计算收入影响需用实际退款金额。","task":"闭卷解释Landed Cost、Gross Margin、Refund Rate。","kind":"复习","minutes":"10–15","fields":["我的理解 / 计算或选择","依据 / 假设 / 下一步"],"quizIds":["12","11"],"sourceIds":[]},{"id":13,"phase":1,"title":"把每一笔订单算到底","topic":"Unit Economics v1","core":"单位经济模型要覆盖每笔订单的全部可变成本。采用统一的“净收入—落地成本—履约—手续费—营销分摊”路径，漏项比算术错误更隐蔽。","example":"假设净收入50元，落地商品成本18元、履约和尾程10元、支付费2元，未包含于净收入的其他售后损失预留2元，每单营销分摊15元。贡献=50−18−10−2−2−15=3元。固定费用还未扣。","takeaway":"50−30−15=5。这还不是公司净利润，也未代表现金已经到账。","task":"完成一组完整Unit Economics。","kind":"实践","minutes":"20–30","fields":["我的理解 / 计算或选择","依据 / 假设 / 下一步"],"quizIds":["13","8"],"sourceIds":["shopify-profit","ifrs-inventory"]},{"id":14,"phase":1,"title":"第二周：把完整成本连起来","topic":"第2周复盘","core":"画出从售价到贡献利润的扣减链。每项标明“真实账单、报价、估算、待补”，经营判断的可信度取决于数据质量。","example":"售价→折扣→净收入→减Landed Cost→减支付/平台费→减达人佣金→减履约/尾程→减退款预留→得到广告前贡献→减CAC→贡献利润。任何一环漏掉，都会高估盈利。","takeaway":"未知成本不等于零。来源和日期能帮助复核、更新并解释决策的不确定性。","task":"画出“售价→最终贡献利润”的完整扣除链。","kind":"复习","minutes":"10–15","fields":["这次学会了什么？留下了什么？","还没弄懂什么？下一步只做哪件事？"],"quizIds":["14","13"],"sourceIds":[]},{"id":15,"phase":1,"title":"一个新客户，值得花多少钱？","topic":"CAC","core":"CAC=获客相关投入÷新增客户数。渠道CAC、整体CAC、付费CAC各有口径。订单数含复购时，不能直接代替新增客户数。","example":"假设获客相关费用1,000元，带来20位新增客户，CAC=50元。同期还有10笔老客订单，总订单30笔，每单营销分摊约33.33元。两个指标用途不同，都应保留清楚口径。","takeaway":"1,000÷20=50元。30笔订单不能直接作为新客数。","task":"写CAC公式并完成3个例子。","kind":"新知","minutes":"15–20","fields":["我的理解 / 计算或选择","依据 / 假设 / 下一步"],"quizIds":["15","13","extra3"],"sourceIds":[],"extra":[{"title":"按客户算，还是按订单算？","core":"CAC的分母是新客户；每单营销费用的分母是订单。一个客户可能多次下单，两项数字回答的问题不同。整期利润应扣实际营销费用总额。"}]},{"id":16,"phase":1,"title":"广告回报漂亮，生意也好吗？","topic":"ROAS / MER","core":"ROAS看广告归因收入÷广告支出；本课程MER指总净收入÷总营销投入。它们需配合利润、退款和归因口径一起判断。","example":"假设广告前贡献率20%，可比口径的广告ROAS为4，即广告花费约占对应收入25%。每100元收入广告前剩20元，广告花费25元，贡献为−5元。广告归因收入不能和其他平台报告简单相加。","takeaway":"每100元收入广告前贡献20元，广告费25元，贡献为−5元。前提是收入、期间和归因口径可比。","task":"解释ROAS与MER差异，并给一个“ROAS高但仍亏”的例子。","kind":"新知","minutes":"15–20","fields":["我的理解 / 计算或选择","依据 / 假设 / 下一步"],"quizIds":["16","15"],"sourceIds":["google-attribution","amazon-acos"]},{"id":17,"phase":1,"title":"流量怎样变成收入？","topic":"AOV / CVR","core":"同口径下：订单数=访问次数×订单转化率，收入=订单数×客单价。平台也可能按转化会话计算CVR，使用前要确认定义。","example":"简化订单口径：10,000次访问×1.5%=150单，客单价50元，收入7,500元。若平台用“发生转化的会话÷会话”而非“订单÷会话”，不能直接混用；退单与税费口径也应一致。","takeaway":"10,000×2%=200单；200×50=10,000元。所有指标应对应同一期间与口径。","task":"写AOV、CVR公式并说明对增长的意义。","kind":"新知","minutes":"15–20","fields":["我的理解 / 计算或选择","依据 / 假设 / 下一步"],"quizIds":["17","1","extra4"],"sourceIds":["shopify-sales","shopify-cro"],"extra":[{"title":"转化率先看分母","core":"转化率不是一个脱离口径的数。Shopify会话转化率看有购买的会话占比；同一会话有多笔订单时，订单数除会话数不是同一指标。比较前还要统一渠道、设备和期间。"}]},{"id":18,"phase":1,"title":"从目标收入反推该做什么","topic":"漏斗计算","core":"收入目标可以拆成访问、转化率和客单价。但目标不是预测；每个提升假设都需要有具体动作和可验证依据。","example":"10,000 Sessions，CVR 1.5%→150 Orders；AOV $49.99→Revenue约$7,498.5。若目标Revenue $10,000且AOV不变，需要约200单；同样10,000 Sessions时目标CVR约2.0%。","takeaway":"10,000÷50=200单。再结合访问量判断转化率目标是否合理。","task":"完成一次Sessions→Orders→Revenue反推。","kind":"新知","minutes":"15–20","fields":["我的理解 / 计算或选择","依据 / 假设 / 下一步"],"quizIds":["18","17"],"sourceIds":["shopify-sales","shopify-cro"]},{"id":19,"phase":1,"title":"复习：指标是一条链","topic":"术语回忆","core":"把流量、订单、新客户和收入分别放到正确位置。同一笔花费可以算不同效率指标，但指标名称和分母必须匹配。","example":"流量通过CVR变订单，订单×AOV变Revenue；营销花费÷新客得到CAC；广告归因收入÷广告费得到ROAS；总收入÷总营销费用得到MER。它们不是五个孤立指标，而是一条流量到收入再到获客效率的链。","takeaway":"CAC的分母是新客户；每单营销分摊的分母是订单。两者在全部为新客且一人一单时才可能相同。","task":"闭卷解释CAC/ROAS/MER/AOV/CVR，并写它们之间的关系。","kind":"复习","minutes":"10–15","fields":["我的理解 / 计算或选择","依据 / 假设 / 下一步"],"quizIds":["19","15"],"sourceIds":["google-attribution","amazon-acos"]},{"id":20,"phase":1,"title":"从流量一路看到利润","topic":"流量到利润模型","core":"先算全期订单贡献：所有订单广告前贡献之和−当期营销支出。单独算CAC用于新客效率，避免把每位新客成本乘全部订单。","example":"假设150笔订单，每笔广告前贡献20元，全期营销支出2,000元，总贡献=150×20−2,000=1,000元。若其中新客100人，CAC=20元；不要再把这个CAC乘以150笔全部订单来扣费。","takeaway":"150×20−2,000=1,000元。营销总额扣一次；不要再用CAC对全部订单重复扣费。","task":"把流量模型与P&L串起来。","kind":"实践","minutes":"20–30","fields":["我的理解 / 计算或选择","依据 / 假设 / 下一步"],"quizIds":["20","15"],"sourceIds":["ga4-ecommerce"],"extra":[{"title":"按客户算，还是按订单算？","core":"CAC的分母是新客户；每单营销费用的分母是订单。一个客户可能多次下单，两项数字回答的问题不同。整期利润应扣实际营销费用总额。"}]},{"id":21,"phase":1,"title":"销售下降，先查哪一段？","topic":"第3周复盘","core":"先验证埋点、支付和数据是否正常，再拆流量、转化、客单价。把问题定位到渠道、设备、商品或新老客，提出可检验假设。","example":"①先看Sessions是否掉；②流量没掉看CVR；③CVR掉再分PDP→ATC→Checkout→Purchase；④成交没掉看AOV/折扣；⑤销售没问题再看CAC、退款、履约后利润。先定位哪一段坏，再谈动作。","takeaway":"先定位变化发生在哪一层，再用细分数据核对原因。相关变化并不能自动证明因果。","task":"写销售下降的5步诊断顺序。","kind":"复习","minutes":"10–15","fields":["这次学会了什么？留下了什么？","还没弄懂什么？下一步只做哪件事？"],"quizIds":["21","17"],"sourceIds":["shopify-cro"]},{"id":22,"phase":1,"title":"复购的价值，需要证据","topic":"LTV / Retention","core":"LTV可以是收入口径或贡献口径，必须写清。判断能承受多少CAC时，更适合看分客户群、固定时间窗的贡献价值和回本时间。","example":"假设同批100位客户在90天内带来收入20,000元、扣除非获客可变成本后贡献8,000元。90天人均收入价值200元，人均贡献价值80元。用于比较CAC时要区分这两者，并检查回款时间和观察期。","takeaway":"用同批客户的实际行为验证，不把远期预测当现金。收入LTV也不能直接等同可用于获客的利润。","task":"解释LTV与Retention，并做高/低复购对比。","kind":"新知","minutes":"15–20","fields":["我的理解 / 计算或选择","依据 / 假设 / 下一步"],"quizIds":["22","15","extra5"],"sourceIds":["shopify-cohorts"],"extra":[{"title":"复购要看留下多少贡献","core":"收入型LTV是客户带来的累计销售额；贡献型LTV还要减商品、履约、支付、售后等可变成本。获客决策要看同一批客户、同样长的观察期，并考虑回本时间。"}]},{"id":23,"phase":1,"title":"找到首单获客的盈亏线","topic":"Break-even CAC","core":"在一位新客一笔首单的简化模型里，首单广告前贡献就是首单盈亏CAC。目标CAC还应为固定费用、波动和利润留出空间。","example":"简化首单模型：一位新客一单，净收入50元，非营销可变成本32元，首单盈亏CAC=18元。该盈亏点只覆盖订单可变成本；不能保证覆盖固定费用，更不能直接套到含老客的全部订单。","takeaway":"50−32=18。若要保留利润和安全余量，目标CAC应低于这个简化盈亏点。","task":"算Break-even CAC并说明用途。","kind":"新知","minutes":"15–20","fields":["我的理解 / 计算或选择","依据 / 假设 / 下一步"],"quizIds":["23","13"],"sourceIds":[]},{"id":24,"phase":1,"title":"你的广告回报最低要多高？","topic":"Break-even ROAS","core":"同收入与费用口径下，盈亏ROAS=1÷广告前贡献率。公式不解决归因偏差，也不覆盖固定费用。","example":"假设同口径收入100元、广告前贡献25元，广告前贡献率25%，简化盈亏ROAS=1÷25%=4。广告归因偏差、复购、固定成本与现金周期仍需另看。","takeaway":"1÷25%=4。每100元收入最多承担25元广告费，才在贡献层面刚好盈亏平衡。","task":"算Break-even ROAS并说明为何不是越高越好。","kind":"新知","minutes":"15–20","fields":["我的理解 / 计算或选择","依据 / 假设 / 下一步"],"quizIds":["24","16","extra6"],"sourceIds":["google-attribution","amazon-acos"],"extra":[{"title":"盈亏线不是行业标准","core":"在销售口径一致、广告前贡献率为正的简化首单模型里，盈亏ROAS=1÷广告前贡献率。它只覆盖已列入的可变成本；房租、工资等固定费用还需另看。"}]},{"id":25,"phase":1,"title":"哪个变量最容易吃掉利润？","topic":"敏感性分析","core":"敏感性分析先一次改变一个变量，其余保持一致，再做组合压力情景。把结果变成动作：优先验证最不确定、影响最大的假设。","example":"基准贡献利润约$0.87。CAC从$15→$12，利润增$3；退款预留$2.5→$5，利润降$2.5；售价提高5%会明显改善利润；佣金从0→15%会直接吃掉约$7.1。结论：该模型最敏感的是售价/折扣、CAC、佣金和退款。","takeaway":"获客成本增加会直接压缩贡献。分析还应考虑涨价、退款、汇率等可能一起变化。","task":"做4项敏感性分析，并找出最敏感变量。","kind":"新知","minutes":"15–20","fields":["我的理解 / 计算或选择","依据 / 假设 / 下一步"],"quizIds":["25","23"],"sourceIds":["google-experiments"]},{"id":26,"phase":1,"title":"复习：利润、现金和时间","topic":"主动回忆","core":"有利润不等于有现金。库存预付款、账期、平台结算和退款会影响可用资金；增长越快，资金占用也可能越大。","example":"假设采购库存先付10,000元，货款30天后才能回收。即使每单贡献为正，这30天仍需要资金支持。比较LTV和CAC时也要看多久能回本，不能只用远期预测支撑眼前支出。","takeaway":"盈利和现金流的时间不同。增长预算还需覆盖库存和回款等待期。","task":"闭卷解释贡献利润、Break-even CAC、LTV之间关系。","kind":"复习","minutes":"10–15","fields":["我的理解 / 计算或选择","依据 / 假设 / 下一步"],"quizIds":["26","22"],"sourceIds":["shopify-cohorts"]},{"id":27,"phase":1,"title":"写出你的第一条经营判断","topic":"真实SKU分析","core":"围绕一个SKU，统一期间与币种，列出收入、完整成本、贡献、数据缺口和下一步动作。结论应明确，并说明哪些证据可能改变它。","example":"SKU/售价/近30天销量与Revenue→Landed Cost→平台/履约→营销费用→CAC/ROAS→退款→贡献毛利→异常点→建议。最后只写一句决策：继续放量 / 先修利润 / 降本 / 停止。缺数据必须标“待补”，不能猜。","takeaway":"可以用假设做情景练习，但真实决策必须保留缺口和条件，不能伪造精确性。","task":"完成1页一个熟悉或模拟的SKU经营分析。","kind":"实践","minutes":"20–30","fields":["我的理解 / 计算或选择","依据 / 假设 / 下一步"],"quizIds":["27","20"],"sourceIds":["shopify-sales"]},{"id":28,"phase":1,"title":"把分析说成一个可决定的问题","topic":"决策Memo","core":"管理表达可用“现状—影响—建议—需要决策”。区分事实与推断，说明方案取舍、负责人和验证时间。","example":"现状：SKU A销售增长，但估算贡献毛利仅3%。影响：继续加预算可能扩大亏损。建议：未来7天冻结放量，优先验证CAC、退款和尾程成本。需要决策：是否批准将20%预算转向利润更健康SKU。附：关键数据与风险。","takeaway":"明确预算、时限和验证安排，能让对方知道要决定什么、如何控制风险。","task":"写一份管理者口吻决策Memo。","kind":"实践","minutes":"20–30","fields":["现状、影响与我的建议","需要谁决定什么？依据与限制是什么？"],"quizIds":["28","27"],"sourceIds":["ccl-feedback"]},{"id":29,"phase":1,"title":"做一个可以反复使用的工具","topic":"P&L Calculator定稿","core":"输入和结果分开；每项费用只扣一次；币种、口径和来源写清。测试空值、零收入与异常费用，不让漂亮结果掩盖缺数据。","example":"输入区与公式区分开；输入至少包含售价、折扣、COGS、Landed Cost组成、支付/平台、佣金、履约、尾程、退款、CAC；输出至少有贡献利润、贡献毛利率、Break-even CAC/ROAS；改任一输入后结果自动更新。","takeaway":"可复用模型的结果必须随有效输入更新。零收入等边界也应有合理提示。","task":"把P&L Calculator做成可重复使用模板。","kind":"实践","minutes":"20–30","fields":["我的理解 / 计算或选择","依据 / 假设 / 下一步"],"quizIds":["29","11"],"sourceIds":["shopify-profit","ifrs-inventory"]},{"id":30,"phase":1,"title":"第一章挑战：独立做一次判断","topic":"Phase 1考试","core":"这一关把概念、算术和决策放到一起。先独立作答，再解释为什么；答错时回到相应知识点，不靠背选项通关。","example":"15个核心术语至少12个能用大白话解释；给一组售价/成本/营销数据能独立算到贡献利润；最后能做1个经营判断。评分：定义30%、计算35%、解释20%、决策15%；≥80分通过。","takeaway":"100−65−40=−5。需要核对完整成本和数据质量，再决定调整或测试。","task":"闭卷完成Phase 1综合考核。","kind":"挑战","minutes":"20–30","fields":["我的理解 / 计算或选择","依据 / 假设 / 下一步"],"quizIds":["30","3","11","15","16","20","23","26"],"sourceIds":["ifrs-principal-agent"]},{"id":31,"phase":2,"title":"给三个渠道分配不同工作","topic":"渠道角色","core":"渠道选择看用户如何发现、比较和购买，以及经济模型与执行能力。平台角色是思考起点，不是适用于所有商品的定律。","example":"Shopify=品牌阵地+第一方数据+复购；Amazon=高意图搜索+信任+履约；TikTok Shop=内容创造需求+达人分销+站内成交。结论：不是三选一，而是按产品/用户/阶段给每个渠道分配角色。","takeaway":"选择要有用户与成本依据，并保留测试空间。渠道协同不意味着平均分配资源。","task":"做Shopify/Amazon/TikTok Shop渠道角色地图。","kind":"新知","minutes":"15–20","fields":["我的理解 / 计算或选择","依据 / 假设 / 下一步"],"quizIds":["31","13"],"sourceIds":["shopify-phishing"]},{"id":32,"phase":2,"title":"把独立站的漏斗拆开看","topic":"Shopify漏斗","core":"访问—商品浏览—加购—结账—购买—复购，每一步都回答不同问题。先核验事件，再按设备与流量来源查掉点。","example":"Traffic→Landing/PDP→ATC→Checkout→Purchase→Repeat。Traffic低查渠道；PDP到ATC低查产品/价格/信任；ATC高Checkout低查运费/支付/结账摩擦；Purchase后不复购查体验、产品周期和CRM。","takeaway":"最靠近掉点的环节应先排查，也要排除统计事件故障。","task":"写Shopify完整漏斗并列每一环常见问题。","kind":"新知","minutes":"15–20","fields":["我的理解 / 计算或选择","依据 / 假设 / 下一步"],"quizIds":["32","17"],"sourceIds":["shopify-cro","ga4-ecommerce"]},{"id":33,"phase":2,"title":"让用户更容易做决定","topic":"CRO","core":"CRO围绕用户障碍：看不懂产品、不信任、怕买错、费用意外、操作困难。用明确假设、小范围改动和守护指标验证。","example":"满分清单至少含：首屏是否3秒说清卖什么；CTA是否可见；产品图/视频是否解释产品；价格价值是否清楚；Review/材质/配送/退换是否降低风险；移动端是否易选购；Checkout是否意外加费；页面速度是否影响体验。","takeaway":"流量、活动和季节可能一起改变。尽可能采用合理对照和足够观察，不把相关性当因果。","task":"做一份CRO检查清单。","kind":"新知","minutes":"15–20","fields":["我的理解 / 计算或选择","依据 / 假设 / 下一步"],"quizIds":["33","21"],"sourceIds":["shopify-cro","google-experiments"]},{"id":34,"phase":2,"title":"复购沟通，从用户需要开始","topic":"CRM / Retention","core":"欢迎、弃购和购后三类沟通对应不同问题。遵守用户授权和适用规则，提供退订、控制频次，不对已购买用户发送冲突信息。","example":"Welcome Flow=品牌/核心利益→热销/教育→首购激励；Abandon Flow=提醒→解决顾虑→最后一次召回；Post-purchase=订单/使用指导→评价→相关复购。每条Flow都要有目标指标，不是只“发邮件”。","takeaway":"先兑现体验和帮助使用，再判断复购时机。用户同意与沟通相关性都很重要。","task":"设计3类基础CRM Flow。","kind":"新知","minutes":"15–20","fields":["我的理解 / 计算或选择","依据 / 假设 / 下一步"],"quizIds":["34","22","extra7"],"sourceIds":["shopify-cohorts","shopify-privacy"],"extra":[{"title":"拿到邮箱，不等于可以随便营销","core":"交易通知和营销推广用途不同。先确认客户的同意与退出选择、目标市场要求和公司规则；只收集完成明确用途所必需的数据。真实客户资料不要放进公开练习或未经批准的工具。"}]},{"id":35,"phase":2,"title":"复习：漂亮页面之外","topic":"复习","core":"把页面问题映射到用户决策与漏斗指标，优先修复真实障碍。视觉优化要有目的，并观察移动端体验与加载表现。","example":"独立站增长不是“把页面做漂亮”，而是合格流量进入→页面降低理解/信任成本→Checkout减少摩擦→邮件/内容经营已获取用户→提高复购和LTV。所有优化都应能对应一个漏斗指标。","takeaway":"这个假设说明用户顾虑、改动与待观察结果；仍需实际验证才能下结论。","task":"闭卷解释Shopify增长链路。","kind":"复习","minutes":"10–15","fields":["我的理解 / 计算或选择","依据 / 假设 / 下一步"],"quizIds":["35","32"],"sourceIds":["shopify-cro"]},{"id":36,"phase":2,"title":"给网站做一次有优先级的体检","topic":"站点审计","core":"审计每项写“可复现事实—影响—建议—验证”。先处理支付不可用、信息错误等阻断，再根据影响与成本排序。","example":"①流量质量；②首屏定位；③产品选择效率；④PDP信息与信任；⑤移动端；⑥Checkout；⑦CRM。每项写“事实→影响→优先级→建议”。示例：移动首屏CTA不可见→影响购买路径→P0→压缩Hero高度。","takeaway":"影响核心购买流程的功能故障优先，完成后验证真实流程与关键设备。","task":"完成1页站点审计。","kind":"实践","minutes":"20–30","fields":["我的理解 / 计算或选择","依据 / 假设 / 下一步"],"quizIds":["36","33","extra8"],"sourceIds":["shopify-cro","ga4-ecommerce","shopify-privacy","google-experiments"],"extra":[{"title":"数据没验收，先别优化广告","core":"报表先检查数据质量：一笔真实订单是否只计一次；币种和金额是否正确；退款是否记录；日期与时区是否一致。给技术同事的要求应能通过测试订单验收。"}]},{"id":37,"phase":2,"title":"这一周，把体验连回经营","topic":"第5周复盘","core":"复盘一次站点改善：原问题是什么、改了什么、指标怎样、还有哪些其他解释。保留没成功的实验和下一步选择。","example":"Shopify最适合承担品牌表达、第一方数据、灵活转化、CRM和高毛利客户沉淀；它不天然提供流量和平台信任。因此做独立站不能只会建站，还必须解决获客、经济模型与复购。","takeaway":"保留条件与不确定性有助于下次更好验证，也避免错误经验被当作固定方法。","task":"总结Shopify在跨境业务里的角色。","kind":"复习","minutes":"10–15","fields":["这次学会了什么？留下了什么？","还没弄懂什么？下一步只做哪件事？"],"quizIds":["37","34"],"sourceIds":["shopify-cohorts","shopify-privacy"]},{"id":38,"phase":2,"title":"看懂平台里的交易机制","topic":"Marketplace机制","core":"平台集中需求、信任与履约服务，同时带来规则、费用和竞争。理解曝光—点击—转化，别把排名变化简化为单一因素。","example":"用户往往带着购买意图搜索→Listing竞争点击和转化→Review/价格/履约影响信任→FBA提升履约体验→广告购买关键词流量→销量和转化又影响自然表现。平台提供需求和信任，但收取费用并限制自由度。","takeaway":"多个环节可能影响销量，平台排序机制也不是可用一句公式保证的结果。","task":"解释Amazon Marketplace机制。","kind":"新知","minutes":"15–20","fields":["我的理解 / 计算或选择","依据 / 假设 / 下一步"],"quizIds":["38","31"],"sourceIds":[]},{"id":39,"phase":2,"title":"Listing：让用户找到，也看懂","topic":"Listing / Ranking","core":"相关关键词帮助匹配意图；图片、功能、规格、评价和配送信息帮助判断。内容需真实一致，避免夸大和关键词堆砌。","example":"Listing的标题/图片/要点帮助获取点击和转化；关键词相关性决定能否参与相关搜索；价格、Review、配送、转化共同影响竞争力。优化不是关键词堆砌，而是同时提高“相关性+点击+转化”。","takeaway":"用户需要准确理解产品是否适合自己。不能凭文案创造不存在的功能。","task":"说明Listing与Ranking的关系。","kind":"新知","minutes":"15–20","fields":["我的理解 / 计算或选择","依据 / 假设 / 下一步"],"quizIds":["39","38"],"sourceIds":[]},{"id":40,"phase":2,"title":"FBA之外，也要看到库存","topic":"FBA / Fees","core":"FBA提供履约服务，商家仍要管理库存、补货、退货与利润。费用随市场、尺寸、类目和时间变化，使用当前官方估算。","example":"先用当前官方收入计算器估算商品对应的销售佣金、FBA配送与仓储等费用，再核对入库、退货、广告和库存处理费用。记录站点、尺寸重量、类目和日期；这些信息变化时重新估算。","takeaway":"库存要结合补货提前期与需求不确定性管理，过量备货会降低现金灵活性。","task":"列出Amazon费用和库存风险。","kind":"新知","minutes":"15–20","fields":["我的理解 / 计算或选择","依据 / 假设 / 下一步"],"quizIds":["40","8","extra9"],"sourceIds":["amazon-pricing","amazon-inventory"],"extra":[{"title":"补货既要算数量，也要算钱","core":"简单补货点=日均需求×补货提前期+安全库存。实务还要核对现货、在途、已分配订单及波动。利润是正数，也可能因预付款、运费和回款滞后而缺现金。"}]},{"id":41,"phase":2,"title":"把广告效率和整体依赖分开","topic":"PPC基础","core":"ACoS=广告花费÷广告归因销售额；TACoS=广告花费÷总销售额。注意收入、期间和广告类型一致，并结合贡献空间。","example":"广告花费200元，广告归因销售额1,000元，总销售额2,000元：ACoS=20%，TACoS=10%。二者都不能独立证明盈利，也不能直接证明广告带来的增量。","takeaway":"200÷1,000=20%；200÷2,000=10%是TACoS，回答的是另一类问题。","task":"解释Amazon PPC/ACoS/TACoS。","kind":"新知","minutes":"15–20","fields":["我的理解 / 计算或选择","依据 / 假设 / 下一步"],"quizIds":["41","16"],"sourceIds":["amazon-acos"]},{"id":42,"phase":2,"title":"复习：平台术语能连起来吗？","topic":"术语回忆","core":"把FBA、Featured Offer、PPC、ACoS放进交易过程。理解它们如何关联，不把任何一项服务视为保证销售的开关。","example":"FBA=Amazon履约；Buy Box/主报价位=核心购买入口；PPC=点击付费广告；ACoS=广告费占广告销售额；TACoS=广告费占总销售额。能讲清“履约、成交入口、广告、整体依赖”四层即通过。","takeaway":"履约是竞争因素之一。主报价位资格与表现有条件，利润仍需要完整计算。","task":"闭卷解释FBA/Buy Box/PPC/ACoS/TACoS。","kind":"复习","minutes":"10–15","fields":["我的理解 / 计算或选择","依据 / 假设 / 下一步"],"quizIds":["42","40"],"sourceIds":["amazon-acos"]},{"id":43,"phase":2,"title":"同一商品，换渠道再算一次","topic":"Amazon Unit Economics","core":"平台交易费、履约、广告和退货会改变单位经济。ACoS不能不加区分地乘到全部订单，混合订单应使用真实广告总额分摊。","example":"假设100单，总净收入5,000元；落地成本1,800元，平台费750元，履约650元，营销总额1,000元，其他未重复计入的售后损失200元。总贡献600元，平均每单6元。费率只是练习假设；用实际总营销费用，避免把广告订单ACoS套到全部销售额。","takeaway":"1,000÷200=5元。这个结果是平均每单分摊，不是按新客数计算的CAC。","task":"做一次Amazon Unit Economics。","kind":"实践","minutes":"20–30","fields":["我的理解 / 计算或选择","依据 / 假设 / 下一步"],"quizIds":["43","20"],"sourceIds":["amazon-pricing","amazon-acos"]},{"id":44,"phase":2,"title":"这个产品适合搜索型渠道吗？","topic":"第6周复盘","core":"检查用户是否主动搜索、商品是否易比较、价值是否清楚、完整成本是否可承受、补货是否稳定。判断用证据和试验修正。","example":"①用户已有明确搜索需求；②产品可标准化比较；③评价能建立信任；④毛利足够覆盖平台/FBA/PPC；⑤库存和补货可控。反例：极度依赖品牌教育、需长故事才能理解的新品，Amazon冷启动更难。","takeaway":"主动搜索需求提供潜在购买意图，但还要核对竞争、价格与成本，不能据此保证成功。","task":"写“什么产品更适合Amazon”的5个维度。","kind":"复习","minutes":"10–15","fields":["这次学会了什么？留下了什么？","还没弄懂什么？下一步只做哪件事？"],"quizIds":["44","38"],"sourceIds":[]},{"id":45,"phase":2,"title":"内容怎样让人产生购买兴趣？","topic":"内容电商模型","core":"有效内容把场景、痛点、演示、证据和下一步连接起来。播放量只代表触达的一部分，需观察点击、成交和退货。","example":"短视频/直播Hook→演示痛点/结果→社会证明/达人信任→站内商品点击→下单→履约→评价/二次内容。与Amazon不同，TikTok往往先创造需求，再完成购买。","takeaway":"娱乐性或广泛传播不一定带来购买意图。先理解用户是否在内容中看见相关价值。","task":"画TikTok Shop内容电商链路。","kind":"新知","minutes":"15–20","fields":["我的理解 / 计算或选择","依据 / 假设 / 下一步"],"quizIds":["45","31"],"sourceIds":["tiktok-shoppable"]},{"id":46,"phase":2,"title":"拆一条内容，不只是抄脚本","topic":"Creative / Content","core":"从开头如何抓住注意、演示如何证明、结尾如何引导三个部分拆解。把事实证据与创意表达分开，保持产品承诺真实。","example":"1：3秒痛点Hook→产品Demo→前后对比→CTA；示例2：反常识/错误用法→正确方法→产品解决→CTA；示例3：真实场景开箱→细节证明→价格/优惠→CTA。拆解时必须写Hook、Proof、CTA三部分。","takeaway":"清楚条件和限制的真实演示更有助于用户判断。未经证实的绝对化承诺会带来体验与规则风险。","task":"拆3条卖货内容结构。","kind":"新知","minutes":"15–20","fields":["我的理解 / 计算或选择","依据 / 假设 / 下一步"],"quizIds":["46","45"],"sourceIds":["tiktok-creative"]},{"id":47,"phase":2,"title":"与达人合作，也是一门小生意","topic":"Creator / Affiliate","core":"先定义目标用户和内容任务，再明确寄样、佣金、交付、使用权与披露要求。先做小样本合作，观察内容与成交质量。","example":"目标=低固定成本测试内容；机制=寄样+15%示例佣金；筛选=受众匹配、内容质量、历史带货；Brief=1个核心痛点+2个Proof，不逐字控稿；衡量=回复率、出片率、点击、GMV、CAC/佣金成本。","takeaway":"粉丝数量不能单独预测成交。要让合作对象、交付目标与利润空间匹配。","task":"设计Creator/Affiliate合作模型。","kind":"新知","minutes":"15–20","fields":["我的理解 / 计算或选择","依据 / 假设 / 下一步"],"quizIds":["47","13"],"sourceIds":["tiktok-shoppable","tiktok-creative"]},{"id":48,"phase":2,"title":"佣金、退款，都会影响结果","topic":"履约与利润","core":"按订单去重核算平台费、达人佣金、广告、履约和售后。样品、内容制作等投入也需进入总体项目预算。","example":"假设每单收入50元，落地成本15、履约6、平台费用3、达人佣金8、其他售后损失预留2，广告前贡献16元。若广告分摊10元，订单贡献6元。寄样与内容制作投入还应计入总体项目评估。","takeaway":"50−15−6−3−8−2=16。广告及其他未计费用仍需另行考虑。","task":"做一次TikTok Shop利润练习。","kind":"新知","minutes":"15–20","fields":["我的理解 / 计算或选择","依据 / 假设 / 下一步"],"quizIds":["48","47"],"sourceIds":[]},{"id":49,"phase":2,"title":"复习：把内容接到履约","topic":"复习","core":"内容承诺、商品页、库存、交付与售后是同一条客户体验链。前端增长不能超过履约能力而无人响应。","example":"内容发现→Creator/品牌账号建立兴趣→商品点击→站内购买→平台/商家履约→评价/退款→佣金结算→内容复用。关键是同时管“创意效率、达人效率、单位经济、履约质量”。","takeaway":"保护客户体验需要真实库存和交付预期。爆量不能替代可履行的订单能力。","task":"闭卷讲TikTok Shop完整交易链路。","kind":"复习","minutes":"10–15","fields":["我的理解 / 计算或选择","依据 / 假设 / 下一步"],"quizIds":["49","10"],"sourceIds":["tiktok-shoppable"]},{"id":50,"phase":2,"title":"用理由给产品打分","topic":"产品适配评分","core":"视觉演示、需求强度、毛利、退货与执行难度可帮助比较。评分是整理判断的工具，权重和证据必须能解释。","example":"（仅方法）：旅行压缩收纳袋=视觉Demo强、痛点直观、合规高，可给较高分；普通补充滤芯=视觉弱、搜索意图更强，分数较低；桌面收纳=中等。评分后必须写一句“为什么”，不能只看总分。","takeaway":"分数常含主观判断。它能帮助优先测试，不能替代真实需求证据。","task":"用1-5分矩阵给3类产品做TikTok适配评分。","kind":"实践","minutes":"20–30","fields":["我的理解 / 计算或选择","依据 / 假设 / 下一步"],"quizIds":["50","45"],"sourceIds":["tiktok-shoppable","tiktok-creative"]},{"id":51,"phase":2,"title":"两种购买路径，两种工作重点","topic":"第7周复盘","core":"有些购买从搜索开始，有些从内容发现开始，也可能交叉。用具体用户路径解释渠道角色，避免把平台标签当绝对规则。","example":"Amazon更像“用户已经想买，我要赢搜索和转化”；TikTok更像“用户原本没在找，我用内容让他突然想买”。前者关键是Listing/Review/FBA/PPC，后者关键是Creative/Creator/Commission/Fulfillment。","takeaway":"购买路径可能跨渠道。分配预算需要结合整体结果和增量证据，而不是简单归功于最后触点。","task":"比较Amazon与TikTok Shop的角色。","kind":"复习","minutes":"10–15","fields":["这次学会了什么？留下了什么？","还没弄懂什么？下一步只做哪件事？"],"quizIds":["51","38"],"sourceIds":["tiktok-shoppable"]},{"id":52,"phase":2,"title":"做渠道选择前，问五个问题","topic":"Channel Strategy","core":"用户在哪里发现问题、如何比较、为何信任、费用能否覆盖、团队能否执行。每个答案都要影响优先级或测试计划。","example":"①用户在哪里发现这个问题/产品？②购买前是主动搜索还是需要教育？③产品是否适合视觉演示？④毛利能否覆盖该渠道费用与获客？⑤该渠道的政策、库存、履约要求我能否承受？","takeaway":"资源是策略的约束。集中有限时间测试关键假设，比无法落实的全渠道表更有用。","task":"写出渠道选择5问。","kind":"新知","minutes":"15–20","fields":["我的理解 / 计算或选择","依据 / 假设 / 下一步"],"quizIds":["52","31"],"sourceIds":[]},{"id":53,"phase":2,"title":"产品和渠道，要相互适配","topic":"Product-Channel Fit","core":"把购买意图、演示需求、价格与履约放在同一框架。给出初始主渠道，再明确什么结果会让你调整选择。","example":"标准搜索型替换滤芯→Amazon主、Shopify辅助；强视觉Demo旅行收纳产品→TikTok主、Amazon承接、Shopify做品牌/CRM；高故事高复购护肤品牌→Shopify+Creator主、Amazon后续承接高意图。","takeaway":"明确型号搜索提示主动意图。仍需要检查兼容信息、竞争、评价与利润。","task":"给3个产品做Product-Channel Fit。","kind":"新知","minutes":"15–20","fields":["我的理解 / 计算或选择","依据 / 假设 / 下一步"],"quizIds":["53","44"],"sourceIds":[]},{"id":54,"phase":2,"title":"谁带来了订单，未必只有一个答案","topic":"Attribution基础","core":"归因分配“功劳”，增量分析问“没有这个动作会怎样”。平台窗口不同可能认领同一订单；先去重，再看整体经营与实验。","example":"用户先看TikTok视频，后搜Google品牌词，再直接访问购买。TikTok、Google和Shopify都可能用自己的归因窗口认领订单。管理者不能简单相加平台“归因Revenue”，要结合总销售、MER、增量测试和路径判断。","takeaway":"订单只发生一次。归因报告可以重叠，不能相加当作真实营收。","task":"解释Attribution为什么会重复算功劳。","kind":"新知","minutes":"15–20","fields":["我的理解 / 计算或选择","依据 / 假设 / 下一步"],"quizIds":["54","16","extra10"],"sourceIds":["ga4-ecommerce","google-attribution","google-lift"],"extra":[{"title":"被广告记功，不等于广告带来增量","core":"归因是在既定规则下分配转化功劳；增量是在尽量可比的对照下估计不投广告就不会发生的结果。平台各自记下的订单可能重叠。"}]},{"id":55,"phase":2,"title":"多渠道库存与促销，要协同","topic":"库存 / 价格一致性","core":"建立可追溯的库存主记录，考虑占用、退货与同步延迟。自营渠道促销需协调，涉及第三方转售定价不能套用通用强制最低价。","example":"为自营渠道制定促销协调与价格信息更新规则；库存考虑已占用订单、在途、退货和同步延迟。对第三方转售商的定价限制涉及具体市场规则，不把“强制统一最低价”作为通用建议。","takeaway":"可售库存应考虑已占用与处理中订单，定期核对同步异常。","task":"列出多渠道库存/价格的3个风险及方案。","kind":"新知","minutes":"15–20","fields":["我的理解 / 计算或选择","依据 / 假设 / 下一步"],"quizIds":["55","40","extra11"],"sourceIds":["amazon-inventory","shopify-phishing"],"extra":[{"title":"店铺账号也属于经营资产","core":"陌生消息用封店、欠费或紧急验证催你操作时，先离开消息，从自己保存的官方入口核实。不给对方密码、验证码或恢复码；团队按职责分配权限，不共用主账号。"}]},{"id":56,"phase":2,"title":"复习：说清角色，也说清代价","topic":"复习","core":"每个渠道用一句话说明角色、一个结果指标、一个主要风险。角色不够清楚时，先缩小目标而不是加更多动作。","example":"Shopify=品牌/数据/复购；Amazon=搜索/信任/履约；TikTok=内容/发现/达人。指标分别偏CVR/LTV/MER、Ranking/ACoS/FBA、Creative/Creator GMV/佣金/CVR。能说清角色+指标+风险即可。","takeaway":"具体目标能关联数据、成本和决策，也有助于团队对齐。","task":"不看资料完成三渠道对比。","kind":"复习","minutes":"10–15","fields":["我的理解 / 计算或选择","依据 / 假设 / 下一步"],"quizIds":["56","54"],"sourceIds":["google-attribution"]},{"id":57,"phase":2,"title":"让一个商品走过三个渠道","topic":"同一SKU三渠道","core":"用同一个SKU练习分工：谁负责发现、谁负责比较成交、谁维护后续关系。统一产品承诺与成本口径，同时尊重渠道规则。","example":"旅行压缩收纳袋——TikTok负责Demo内容和达人创造需求；Amazon承接“travel compression bags”等高意图搜索及FBA成交；Shopify放品牌故事、套装、Email收集与复购。三渠道共用一套P&L底线，但KPI不同。","takeaway":"用户跨渠道比较时，信息冲突会损害信任，也会造成售后和履约问题。","task":"用同一SKU设计三渠道分工。","kind":"实践","minutes":"20–30","fields":["我的理解 / 计算或选择","依据 / 假设 / 下一步"],"quizIds":["57","53"],"sourceIds":[]},{"id":58,"phase":2,"title":"把渠道方案写成一个取舍","topic":"渠道决策Memo","core":"明确主渠道、投入上限、验证目标和改道条件。讨论不仅是“做什么”，也包括“现阶段先不投入什么”。","example":"现状：产品视觉演示性强、搜索需求也存在。建议：首60天TikTok做需求测试，Amazon同步承接高意图，Shopify不承担主要冷启动流量。理由：内容可快速验证卖点，同时避免独立站单独扛获客。需要决策：首月预算与库存上限。","takeaway":"决策需要证据、代价和调整条件，不能只停留在平台偏好。","task":"写渠道决策Memo。","kind":"实践","minutes":"20–30","fields":["现状、影响与我的建议","需要谁决定什么？依据与限制是什么？"],"quizIds":["58","52"],"sourceIds":["google-lift","ccl-feedback"]},{"id":59,"phase":2,"title":"用一页讲清渠道策略","topic":"1页Channel Strategy","core":"把用户路径、主辅渠道、指标、预算、负责人、节奏与风险连起来。每项资源投入都应服务一个可以检查的目标。","example":"目标用户→购买路径→主渠道→辅助渠道→每渠道角色→核心KPI→预算原则→库存/价格规则→最大风险→30/60/90天动作。关键：渠道之间不能只是“都做”，必须有主次和接力关系。","takeaway":"清楚的责任与验收能减少等待和反复，让策略变成可以推进的项目。","task":"完成1页Channel Strategy。","kind":"实践","minutes":"20–30","fields":["我的理解 / 计算或选择","依据 / 假设 / 下一步"],"quizIds":["59","58"],"sourceIds":[]},{"id":60,"phase":2,"title":"第二章挑战：为选择负责","topic":"Phase 2考试","core":"比较渠道时要同时讨论用户、单位经济、执行能力和风险。没有适合所有产品的渠道答案，关键是理由可验证。","example":"随机拿3个产品，每个用3分钟回答“主渠道、辅助渠道、理由、核心指标、最大风险”。评分：产品-渠道匹配35%、单位经济25%、指标20%、风险/执行20%。≥80分且没有明显平台角色混淆为通过。","takeaway":"曝光不是可持续增长的充分条件。先定位转化与成本问题，再决定是否继续。","task":"Phase 2综合考试。","kind":"挑战","minutes":"20–30","fields":["我的理解 / 计算或选择","依据 / 假设 / 下一步"],"quizIds":["60","31","33","40","41","48","54","55"],"sourceIds":[]},{"id":61,"phase":3,"title":"选一个问题，完成整套案例","topic":"选品","core":"选一个你能理解、资料可获得的普通商品。明确这一轮是学习与验证项目，用小范围研究检验假设，不急于采购和上线。","example":"（仅示范，不代表真实市场结论）：选择“可重复使用旅行压缩收纳袋套装”。理由：痛点可视觉演示；Amazon存在搜索承接逻辑；TikTok适合前后对比内容；Shopify可做套装/品牌。下一步必须用真实证据验证需求与竞争。","takeaway":"可验证与可完成优先。学习案例也应标明模拟内容，不能把假设当市场结论。","task":"选1个普通非监管产品并写选品理由。","kind":"新知","minutes":"15–20","fields":["本关的案例结论 / 交付内容","证据链接或假设，以及下一步验证"],"quizIds":["61","50"],"sourceIds":[]},{"id":62,"phase":3,"title":"用户是谁，正在解决什么？","topic":"用户问题","core":"用情境、任务、困难和替代方案描写用户。人口标签只提供部分背景，真正的购买动机要从行为和问题里找。","example":"用户=经常短途/廉航旅行、行李空间敏感的人；场景=3–7天旅行打包；问题=衣物占空间、行李混乱；现有替代=普通收纳袋/真空袋/少带衣服；购买触发=出发前、行李超重/塞不下。","takeaway":"场景和任务更能推导功能、卖点与渠道。年龄标签本身不能说明购买原因。","task":"写清核心用户、场景、痛点、替代方案。","kind":"新知","minutes":"15–20","fields":["本关的案例结论 / 交付内容","证据链接或假设，以及下一步验证"],"quizIds":["62","53"],"sourceIds":[]},{"id":63,"phase":3,"title":"找证据，而不只找支持","topic":"需求证据","core":"记录来源、日期、原话或数据、与你假设的关系。主动寻找反例，区分需求信号、购买意愿与真正付费。","example":"不是固定数字，而是证据结构：①Google/Amazon搜索趋势或关键词；②竞品Review高频痛点；③TikTok/Reddit用户讨论；④同类畅销/评论量；⑤价格接受信号。每条必须保存URL/截图/日期，并标“事实/推断”。禁止把示例数字当真实数据。","takeaway":"互动、意向和支付是不同强度的信号。证据应与要判断的问题匹配。","task":"收集至少5条真实需求证据。","kind":"实践","minutes":"20–30","fields":["本关的案例结论 / 交付内容","证据链接或假设，以及下一步验证"],"quizIds":["63","54"],"sourceIds":["google-experiments"]},{"id":64,"phase":3,"title":"从竞品里读出未解决的问题","topic":"竞品地图","core":"比较价格、规格、卖点和真实反馈。低分评价可能揭示问题，也可能只代表少数场景；交叉核对，不机械照抄。","example":"品牌/产品、价格、套装数量、核心卖点、评分/评论信号、主要渠道、内容角度、差评高频、你的机会。不要写“竞品很强/很弱”这种空话，要从具体差评或定位差异推出机会。","takeaway":"单条反馈是线索，不是普遍性的证明。注意样本偏差和评价真实性。","task":"完成5–10个竞品地图。","kind":"实践","minutes":"20–30","fields":["本关的案例结论 / 交付内容","证据链接或假设，以及下一步验证"],"quizIds":["64","63"],"sourceIds":[]},{"id":65,"phase":3,"title":"给证据一个能找回来的家","topic":"整理资料","core":"每条资料保留来源链接、日期、摘要、事实或推断标签和用途。整理围绕决策，避免只收藏却无法引用。","example":"文件夹：01_Market、02_Competitors、03_Reviews、04_Content、05_Cost、06_Logistics、07_Policies。每个文件命名“日期_来源_主题”；商业案例中的每个重要结论都能回到某个证据链接。","takeaway":"可追溯记录允许复核，也能在信息过期或被反驳时更新结论。","task":"把资料整理成可追溯证据库。","kind":"复习","minutes":"10–15","fields":["本关的案例结论 / 交付内容","证据链接或假设，以及下一步验证"],"quizIds":["65","63"],"sourceIds":["shopify-phishing"]},{"id":66,"phase":3,"title":"细分用户，看不同的取舍","topic":"用户细分","core":"不同群体可能有不同任务、预算与替代品。先选择一个核心细分，用其需求决定产品取舍，再考虑扩展。","example":"A：效率型频繁旅行者——重视节省空间、快速整理、耐用；触发=廉航/短途。B：家庭出游组织者——重视分类和减少混乱；触发=多人旅行。不要把“25-35岁女性”当核心画像，需求和行为比人口标签更重要。","takeaway":"有限资源需要明确服务对象。全覆盖往往让价值表达和产品成本失去重点。","task":"做1–2个核心用户细分。","kind":"新知","minutes":"15–20","fields":["本关的案例结论 / 交付内容","证据链接或假设，以及下一步验证"],"quizIds":["66","62"],"sourceIds":[]},{"id":67,"phase":3,"title":"找到最值得先验证的未知","topic":"第9周复盘","core":"把不确定性按“如果错了影响多大”和“目前证据有多弱”排序。优先用低成本动作验证能改变决定的问题。","example":"最大不确定性不是“页面长什么样”，而是目标用户是否愿意为更好的压缩/耐用性支付溢价。下周优先验证价格接受与差评痛点：看Review、竞品价位、内容评论，再决定差异化，而不是先做Logo。","takeaway":"优先解决会改变项目方向的未知。越早获得关键信息，越能减少无效投入。","task":"写第9周最大不确定性与验证优先级。","kind":"复习","minutes":"10–15","fields":["这次学会了什么？留下了什么？","还没弄懂什么？下一步只做哪件事？"],"quizIds":["67","50"],"sourceIds":["google-experiments"]},{"id":68,"phase":3,"title":"差异化，要有事实支撑","topic":"差异化","core":"定位要说明给谁、在哪个场景、带来什么可证实的优势。功能、质量和效果承诺都需要与真实产品能力一致。","example":"（假设）：定位：“给经常旅行的人，更快整理、无需抽气泵的可重复压缩收纳系统。”证据方向：双拉链机械压缩；耐用面料/结构；尺寸组合更适合随身/登机箱。真实案例必须用产品事实支撑，不能凭文案创造功能。","takeaway":"数值承诺需要可核验依据。真实规格与实际演示比虚构优势更可靠。","task":"写一句定位+3条差异化证据。","kind":"实践","minutes":"20–30","fields":["本关的案例结论 / 交付内容","证据链接或假设，以及下一步验证"],"quizIds":["68","46"],"sourceIds":["tiktok-creative"]},{"id":69,"phase":3,"title":"定价是一组需要验证的假设","topic":"定价梯度","core":"价格要同时考虑用户价值、替代方案、完整成本和渠道费用。比较不同价位时也考虑转化、退款和贡献，而不只看销量。","example":"（假设）：$29.99低价易转化但毛利薄；$39.99中档兼顾毛利与竞争；$49.99高价需要更强材质/品牌证明。选择$39.99作为测试价，原因：单位经济有空间，同时不要求一开始承担过高品牌溢价。","takeaway":"低价可能牺牲每单贡献，也可能提升总贡献；需用同口径实际数据比较。","task":"设计低/中/高三档价格并做取舍。","kind":"实践","minutes":"20–30","fields":["本关的案例结论 / 交付内容","证据链接或假设，以及下一步验证"],"quizIds":["69","25"],"sourceIds":[]},{"id":70,"phase":3,"title":"让每个成本假设有出处","topic":"成本假设","core":"为成本记录报价或官方来源、计费单位、币种、时间和有效期。汇率、体积重、最低量和售后费用都可能改变模型。","example":"（假设）：采购$9、包装$1、头程$2、关税/入仓$1.5→Landed Cost $13.5；履约$5.5、支付/平台按渠道计、退款预留$2。每一项要标“报价/公开费率/假设”，后续用真实数据逐项替换。","takeaway":"报价边界不明时不能直接比较。确认交货地点、费用责任与计费条件。","task":"建立完整成本假设。","kind":"实践","minutes":"20–30","fields":["本关的案例结论 / 交付内容","证据链接或假设，以及下一步验证"],"quizIds":["70","8"],"sourceIds":["amazon-pricing","ifrs-inventory"]},{"id":71,"phase":3,"title":"把案例里的生意算出来","topic":"P&L v1","core":"用一致的成本结构跑通一个SKU，设置基准、较差和较好情景。真实数据与假设明确分开，先找亏损风险再美化模型。","example":"（假设）：售价$39.99，Landed $13.5，支付$1.2，履约/尾程$7.5，退款$2，则广告前剩约$15.79；Break-even CAC约$15.79。若预计CAC $12，则贡献约$3.79/单。结论：可以测试，但利润安全垫不大。","takeaway":"情景分析帮助暴露风险。可承受的投入和验证顺序应由风险共同决定。","task":"完成Business Case P&L v1。","kind":"实践","minutes":"20–30","fields":["本关的案例结论 / 交付内容","证据链接或假设，以及下一步验证"],"quizIds":["71","23"],"sourceIds":["ifrs-inventory"]},{"id":72,"phase":3,"title":"复习：用自己的案例解释术语","topic":"术语回忆","core":"把每个术语指向案例中的具体字段、公式或决定。讲不清的地方往往是模型口径或业务理解还未打通。","example":"至少能脱稿解释售价、Landed Cost、Gross Margin、Contribution Profit、CAC、Break-even CAC、ROAS、CVR、AOV、Refund Rate，并且每个词都能指向自己案例里的一个数字。","takeaway":"能定义、计算并解释作用，比只记忆名称更接近可应用的理解。","task":"闭卷解释本案例实际用到的财务术语。","kind":"复习","minutes":"10–15","fields":["本关的案例结论 / 交付内容","证据链接或假设，以及下一步验证"],"quizIds":["72","15"],"sourceIds":[]},{"id":73,"phase":3,"title":"把风险变成可比较的情景","topic":"敏感性分析","core":"用合理范围变化价格、成本、CAC、退款与汇率。不要把所有最好假设同时叠加当基准，关注现金和贡献的下行风险。","example":"测试价$34.99/$39.99/$44.99；CAC $8/$12/$16；退款5%/10%；佣金10%/15%/20%。输出不是一堆数字，而是结论：项目最怕CAC>盈亏线和达人佣金过高；因此首轮测试优先验证内容获客成本。","takeaway":"正确公式无法弥补偏乐观输入。需保留基准依据及下行情景。","task":"对Business Case做敏感性分析。","kind":"实践","minutes":"20–30","fields":["本关的案例结论 / 交付内容","证据链接或假设，以及下一步验证"],"quizIds":["73","25","extra12"],"sourceIds":["google-lift","google-experiments"],"extra":[{"title":"小测试也需要清楚的假设","core":"先写“改什么、为什么、看什么结果”。起步时一次比较一个变量，设好主要指标、预算和观察窗口。数据不足或结果不确定可以继续观察，不能因为一天领先就宣布成功。"}]},{"id":74,"phase":3,"title":"提前回答：哪里最可能失败？","topic":"第10周复盘","core":"风险写成具体事件、影响、早期信号和应对。供应、质量、需求、获客和现金互相关联，需明确谁负责监测。","example":"①用户觉得普通收纳袋已够用，溢价不成立；②TikTok内容有观看但购买弱，CAC超盈亏线；③竞品价格压制导致只能打折；④材质/拉链退货率高。每个风险都写对应验证：评论、价格测试、内容测试、样品耐用测试。","takeaway":"明确触发条件、责任人和动作，才能在风险出现时快速响应。阈值需结合实际调整。","task":"写“这门生意最可能死在哪里”。","kind":"复习","minutes":"10–15","fields":["这次学会了什么？留下了什么？","还没弄懂什么？下一步只做哪件事？"],"quizIds":["74","40"],"sourceIds":[]},{"id":75,"phase":3,"title":"写一份能落地的平台计划","topic":"Amazon计划","core":"连接用户搜索、Listing、履约、广告、补货和费用。评价策略遵守平台规则，不把购买好评或违规激励当增长手段。","example":"目标关键词/搜索意图→Listing主卖点→图片/视频→FBA方案→价格→Review/合规策略→PPC测试→ACoS/TACoS底线→库存补货点。重点：所有广告目标必须受P&L盈亏线约束。","takeaway":"需求增长、采购和回款时间需协调。提前期会影响补货点与资金需求。","task":"完成Amazon 1页计划。","kind":"实践","minutes":"20–30","fields":["本关的案例结论 / 交付内容","证据链接或假设，以及下一步验证"],"quizIds":["75","43"],"sourceIds":["amazon-pricing","amazon-inventory","amazon-acos"]},{"id":76,"phase":3,"title":"给内容测试一个清晰边界","topic":"TikTok计划","core":"每轮测试固定核心目标，变化有意义的创意要素，记录投入与结果。达人合作、素材使用、履约和售后都纳入预算与验收。","example":"3个内容角度→首批20–30条创意测试→Creator筛选→佣金假设→寄样规则→站内商品页→履约→核心KPI（视频点击、CVR、Creator出片/GMV、CAC）→淘汰规则。数字为示例时必须标假设。","takeaway":"多个变量同时变化会影响解释。探索时可广泛试，但归因结论要谨慎。","task":"完成TikTok Shop 1页计划。","kind":"实践","minutes":"20–30","fields":["本关的案例结论 / 交付内容","证据链接或假设，以及下一步验证"],"quizIds":["76","33"],"sourceIds":["tiktok-shoppable","tiktok-creative"]},{"id":77,"phase":3,"title":"把品牌站做成可靠的承接点","topic":"Shopify计划","core":"页面要回答卖什么、适合谁、为什么信任、如何选、多久到、如何售后。先确保手机购买流程，再优化展示与复购。","example":"角色=品牌/套装/第一方数据，不承担全部冷启动；Landing首屏=问题+Demo+CTA；PDP=尺寸/材质/对比/FAQ/物流；Email=Welcome/Abandon/Post-purchase；指标=CVR、AOV、CAC、Email capture、Repeat。","takeaway":"核心任务可完成是体验基础。功能修复后再用真实设备确认。","task":"完成Shopify 1页计划。","kind":"实践","minutes":"20–30","fields":["本关的案例结论 / 交付内容","证据链接或假设，以及下一步验证"],"quizIds":["77","32"],"sourceIds":["shopify-cro","shopify-privacy"],"extra":[{"title":"拿到邮箱，不等于可以随便营销","core":"交易通知和营销推广用途不同。先确认客户的同意与退出选择、目标市场要求和公司规则；只收集完成明确用途所必需的数据。真实客户资料不要放进公开练习或未经批准的工具。"}]},{"id":78,"phase":3,"title":"让内容、搜索与复购接力","topic":"SEO / Creator / CRM","core":"同一用户问题可产生演示、帮助文章和购后指导。让团队共用真实产品信息、素材使用边界与衡量方法，避免各自重复。","example":"Creator负责快速制造内容与信任；SEO承接长期“travel packing/compression”问题型搜索；CRM把已有访问/买家变成复购和推荐。三者不是三个孤立部门，而是“获客→信任→沉淀”的接力。","takeaway":"统一事实与工作边界能减少误解。协作还需明确交接时间和遇到冲突的处理方式。","task":"定义SEO / Creator / CRM的协同。","kind":"实践","minutes":"20–30","fields":["本关的案例结论 / 交付内容","证据链接或假设，以及下一步验证"],"quizIds":["78","34"],"sourceIds":["shopify-cohorts","shopify-privacy"]},{"id":79,"phase":3,"title":"让每个结论都能被追问","topic":"资料整理","core":"对关键论断标记事实、推断或假设，并连回来源。公开报告和个人客户数据分开，去除不必要的身份信息。","example":"市场、竞品、评论、内容、成本、物流、政策每个结论都有来源；截图带日期；表格里保留URL；假设用黄色/“Assumption”标记；事实和推断绝不混在一起。删除只“有意思但不支持决策”的收藏。","takeaway":"展示价值不需要暴露无关个人信息。使用数据前需核对授权与适用要求。","task":"整理所有证据与引用。","kind":"复习","minutes":"10–15","fields":["本关的案例结论 / 交付内容","证据链接或假设，以及下一步验证"],"quizIds":["79","65"],"sourceIds":["shopify-phishing"]},{"id":80,"phase":3,"title":"把风险接到客户与现金","topic":"物流 / 退货 / 合规风险","core":"物流、质量、库存、政策与收款会共同影响经营。具体税务、合规和产品限制需按市场查证，课程示例不替代正式判断。","example":"物流=体积重/尾程成本；库存=爆单断货与滞销；退货=拉链/耐用问题导致退款；合规=材质声明、标签、平台规则；现金流=首批库存和达人样品占用。每项写概率、影响、预防和触发动作。","takeaway":"验证码和密码不能交给来历不明的联系人。用已知官方入口核对账户状态。","task":"做物流/退货/合规风险清单。","kind":"实践","minutes":"20–30","fields":["本关的案例结论 / 交付内容","证据链接或假设，以及下一步验证"],"quizIds":["80","55","extra13"],"sourceIds":["amazon-inventory","shopify-phishing","shopify-privacy"],"extra":[{"title":"补货既要算数量，也要算钱","core":"简单补货点=日均需求×补货提前期+安全库存。实务还要核对现货、在途、已分配订单及波动。利润是正数，也可能因预付款、运费和回款滞后而缺现金。"},{"title":"店铺账号也属于经营资产","core":"陌生消息用封店、欠费或紧急验证催你操作时，先离开消息，从自己保存的官方入口核实。不给对方密码、验证码或恢复码；团队按职责分配权限，不共用主账号。"},{"title":"政策与费用要带适用范围","core":"看规则时记录站点、国家/地区、品类、发布日期与生效日。供应商说能卖不等于平台允许；产品说明、标签、素材和费用都要根据目标市场逐项核实。"}]},{"id":81,"phase":3,"title":"预算减半，保留哪些动作？","topic":"第11周复盘","core":"优先保留保护客户、验证关键未知和维持必要履约的动作。明确暂停项与影响，重新对齐目标，而不要求同样资源做所有事。","example":"保留能验证最大风险的动作：样品质量、少量库存、核心创意测试、关键Creator；砍掉大规模品牌拍摄、过早SEO内容铺量、复杂网站功能和大预算广告。原则：先买“信息”，再买“规模”。","takeaway":"不同任务的必要性和信息价值不同。负责人需要做明确取舍并向相关方沟通。","task":"预算砍50%时做优先级判断。","kind":"复习","minutes":"10–15","fields":["这次学会了什么？留下了什么？","还没弄懂什么？下一步只做哪件事？"],"quizIds":["81","52"],"sourceIds":["google-experiments"]},{"id":82,"phase":3,"title":"把计划拆成可交接的任务","topic":"90天上市节奏","core":"每项任务写负责人、交付物、截止日、验收与依赖。阶段推进看条件是否满足，不能只因日历到了就放量。","example":"Day 1–30准备/验证：样品、成本、Listing/页面、20条创意；31–60测试：小预算广告+Creator+首批订单，验证CVR/CAC/退款；61–90仅对通过阈值的渠道放量，同时补货、CRM、SEO。每阶段都有进入下一阶段条件。","takeaway":"依赖关系决定排期和阻塞。先暴露等待点，再安排可并行的工作。","task":"做90天Launch Calendar。","kind":"实践","minutes":"20–30","fields":["本关的案例结论 / 交付内容","证据链接或假设，以及下一步验证"],"quizIds":["82","59","extra14"],"sourceIds":["amazon-inventory","ccl-feedback"],"extra":[{"title":"交任务，要让对方知道怎样才算完成","core":"任务至少说明负责人、交付物、截止时间、验收标准和检查点；再确认资源与障碍。负责人不等于独自做完一切，而是负责推动结果与及时暴露风险。"}]},{"id":83,"phase":3,"title":"看板上的数字，要触发动作","topic":"KPI Dashboard","core":"选择少量结果指标、前置指标和守护指标。每项写口径、周期、数据源、阈值、负责人和对应动作。","example":"北极星=Contribution Profit或可持续订单；前置指标=合格流量、CTR、CVR、CAC；业务指标=AOV、退款、贡献毛利；渠道指标=ACoS/TACoS、Creator GMV等。每个指标要有目标/预警/实际/趋势/动作。","takeaway":"预警应连接调查与执行。阈值需适应样本规模、品类和时间窗。","task":"做KPI Dashboard。","kind":"实践","minutes":"20–30","fields":["本关的案例结论 / 交付内容","证据链接或假设，以及下一步验证"],"quizIds":["83","21"],"sourceIds":["shopify-sales","ga4-ecommerce","google-attribution","amazon-acos"],"extra":[{"title":"数据没验收，先别优化广告","core":"报表先检查数据质量：一笔真实订单是否只计一次；币种和金额是否正确；退款是否记录；日期与时区是否一致。给技术同事的要求应能通过测试订单验收。"}]},{"id":84,"phase":3,"title":"预算买到什么，要能解释","topic":"预算分配","core":"为每笔投入说明目标、假设、上限、观察窗口与停止条件。保留履约和现金余量，根据证据分阶段释放预算。","example":"（仅假设）：40%内容/Creator测试，25%Amazon搜索/PPC，15%Shopify/CRM基础，10%样品/UGC，10%预备金。不是平均分；预算应该集中在最大不确定性的验证上，并预留根据数据重新分配的空间。","takeaway":"分阶段投入能在获得新信息后调整。投入规模需符合可承受损失与执行能力。","task":"做预算分配并解释逻辑。","kind":"实践","minutes":"20–30","fields":["本关的案例结论 / 交付内容","证据链接或假设，以及下一步验证"],"quizIds":["84","71"],"sourceIds":["google-lift","amazon-inventory"]},{"id":85,"phase":3,"title":"什么时候调整，什么时候停止？","topic":"Kill Criteria","core":"预先定义观察窗口、数据质量要求、阈值和触发动作。小样本失败不能自动证明没有需求，严重安全或规则问题则需及时处理。","example":"例：先定义预算上限、有效流量标准、观察窗口与数据质量，再约定“达到何种证据后暂停、修改或追加验证”。阈值由产品利润、可承受损失与样本量决定；课程数字不是所有商品通用的止损线。","takeaway":"停止规则应兼顾证据量、成本上限与风险，避免过早或无止境地测试。","task":"预设至少5条Kill Criteria。","kind":"实践","minutes":"20–30","fields":["本关的案例结论 / 交付内容","证据链接或假设，以及下一步验证"],"quizIds":["85","63"],"sourceIds":["google-lift","google-experiments"],"extra":[{"title":"小测试也需要清楚的假设","core":"先写“改什么、为什么、看什么结果”。起步时一次比较一个变量，设好主要指标、预算和观察窗口。数据不足或结果不确定可以继续观察，不能因为一天领先就宣布成功。"}]},{"id":86,"phase":3,"title":"五分钟，讲清一门生意","topic":"主动回忆","core":"按用户问题、证据、产品、经济模型、渠道、执行、风险与请求讲述。听众应能判断“为什么做、如何验证、需要决定什么”。","example":"30秒用户问题→45秒需求证据→45秒产品/差异化→60秒Unit Economics→60秒渠道策略→45秒Launch→30秒最大风险/Kill Criteria→30秒结论。能在不看表格的情况下讲清因果，而不是背术语。","takeaway":"先服务听众的决定。细节可留在附件或后续提问中。","task":"5分钟脱稿讲完整门生意。","kind":"复习","minutes":"10–15","fields":["现状、影响与我的建议","需要谁决定什么？依据与限制是什么？"],"quizIds":["86","28"],"sourceIds":["ccl-feedback"]},{"id":87,"phase":3,"title":"让商业方案有一条主线","topic":"10–15页大纲","core":"每页回答一个问题，页面之间形成推理链。结论先行，数据与来源支持判断，删去与决策无关的堆积内容。","example":"12页：1 Executive Summary；2 User Problem；3 Demand Evidence；4 Competitor Map；5 Product/Positioning；6 Pricing；7 Unit Economics；8 Channel Strategy；9 Amazon；10 TikTok+Shopify；11 90-Day Launch/KPI；12 Risks/Kill Criteria/Recommendation。","takeaway":"清楚的主张让读者知道如何理解后续证据，也方便检验逻辑。","task":"完成10–15页Business Case大纲。","kind":"实践","minutes":"20–30","fields":["现状、影响与我的建议","需要谁决定什么？依据与限制是什么？"],"quizIds":["87","59"],"sourceIds":[]},{"id":88,"phase":3,"title":"把作品磨到经得起检查","topic":"案例定稿","core":"检查数字能否对上、假设是否可见、证据是否过期、任务是否有责任人。作品质量由可理解、可复核、可执行共同决定。","example":"结论先行；每个关键判断有证据；事实/假设分开；P&L公式自洽；渠道有主次；Launch有阶段和指标；Risk/Kill Criteria具体；视觉简洁；任何人看10分钟能明白“为什么做/怎么赚钱/什么时候停”。","takeaway":"让不确定性可见是负责任的判断。结论强度应与证据强度匹配。","task":"完成可展示Business Case V1.0。","kind":"实践","minutes":"20–30","fields":["本关的案例结论 / 交付内容","证据链接或假设，以及下一步验证"],"quizIds":["88","79"],"sourceIds":[]},{"id":89,"phase":3,"title":"面对质疑，回到证据与取舍","topic":"模拟汇报","core":"先确认问题，解释依据与限制，再提出下一步验证。给同事反馈时描述具体行为和影响，并一起确定下一步，避免人格标签。","example":"满分问题示例：①为什么选这个品？②为什么先TikTok而不是Amazon？③CAC比预期高30%怎么办？④预算砍一半保什么？⑤什么情况下你会停？回答必须引用自己的证据、P&L和Kill Criteria，而不是“我觉得”。","takeaway":"具体事实和影响更可讨论。听取背景后共同确定支持、责任与检查时间。","task":"模拟回答5个老板/面试官质疑。","kind":"实践","minutes":"20–30","fields":["现状、影响与我的建议","需要谁决定什么？依据与限制是什么？"],"quizIds":["89","28","extra15"],"sourceIds":["ccl-feedback"],"extra":[{"title":"反馈说事实，也听对方的原因","core":"可以用情境—行为—影响组织反馈：在哪次任务、观察到什么、造成什么影响。再询问对方遇到的困难，与对方约定下一步。不要把一次行为直接变成人格标签。"}]},{"id":90,"phase":3,"title":"90关之后，带着作品继续向上","topic":"90天总复盘","core":"回顾已能独立完成的任务、留下的证据和仍需练习的能力。把下一阶段聚焦到一个真实项目，领导力在承担责任与协作中继续形成。","example":"我从什么起点来→掌握哪些术语/模型→完成哪些作品→哪3项能力变化最大→哪3个弱项仍明显→工作中应用了什么→下一90天只选1条主线→要争取的Owner项目→职业岗位目标与证据缺口。","takeaway":"课程提供基础与练习；真实场景里的决策、反馈和结果能进一步检验并发展能力。","task":"完成90天总复盘和下一阶段计划。","kind":"挑战","minutes":"20–30","fields":["这次学会了什么？留下了什么？","还没弄懂什么？下一步只做哪件事？"],"quizIds":["90","63","68","71","79","82","85","89"],"sourceIds":["ccl-feedback"],"extra":[{"title":"反馈说事实，也听对方的原因","core":"可以用情境—行为—影响组织反馈：在哪次任务、观察到什么、造成什么影响。再询问对方遇到的困难，与对方约定下一步。不要把一次行为直接变成人格标签。"}]}],"questions":{"1":{"id":"1","lesson":1,"prompt":"一家平台促成10,000元交易，只收10%佣金；简化忽略其他收入，平台收入是多少？","options":["1,000元","10,000元","9,000元"],"answer":0,"explanation":"平台的交易额不等于平台自己的收入。此例平台收入为佣金10,000×10%=1,000元；商品卖家的收入要另算。"},"2":{"id":"2","lesson":2,"prompt":"采购成本已包含每件2元头程，计算利润时应该怎么处理？","options":["保留成本明细，不重复扣头程","再扣一次，更保守","把头程当广告费"],"answer":0,"explanation":"重复计费会低估利润。先说明每个成本字段包含哪些项目，再进行相加。"},"3":{"id":"3","lesson":3,"prompt":"一个商品净销售收入100元，已售商品成本40元，毛利率是多少？","options":["60%","40%","150%"],"answer":0,"explanation":"毛利为60元，毛利率为60÷100=60%。60÷40是相对成本的加价比例，口径不同。"},"4":{"id":"4","lesson":4,"prompt":"售价80元，商品成本36元，毛利是多少？","options":["44元","55元","80元"],"answer":0,"explanation":"80−36=44元；55%是毛利率。金额和比例不要混写。"},"5":{"id":"5","lesson":5,"prompt":"哪一句解释最准确？","options":["毛利是收入扣除已售商品成本后的余额","GMV就是净利润","收入就是银行卡余额"],"answer":0,"explanation":"确认收入、收到现金和最终利润是不同概念。一个订单可以产生收入，却仍有成本和待收款。"},"6":{"id":"6","lesson":6,"prompt":"订单贡献利润为正，能否证明公司整体盈利？","options":["不能，还需覆盖固定费用等项目","能，每单都赚钱就够了","只要订单多就能证明"],"answer":0,"explanation":"办公、薪资、订阅等固定或期间费用仍可能让整体亏损。订单贡献和公司净利润的边界不同。"},"7":{"id":"7","lesson":7,"prompt":"哪条复盘最能推动下一周行动？","options":["还缺尾程费用，周二核对仓库报价","这周看了很多知识","以后要更加努力"],"answer":0,"explanation":"具体缺口、可执行动作和时间，让复盘能转为行动。阅读数量不能直接证明理解。"},"8":{"id":"8","lesson":8,"prompt":"采购12、包装1、头程2、关税1、入库1，互不重复，落地成本是多少？","options":["17","12","15"],"answer":0,"explanation":"五项相加为17。计算前需确认报价是否已经包含其中部分项目。"},"9":{"id":"9","lesson":9,"prompt":"商品换类目后，最合理的费用处理是？","options":["查对应市场与类目的当前官方费表","沿用所有类目统一15%","只看竞品售价"],"answer":0,"explanation":"固定费率不是通用事实。把费率来源和核对日期写入模型，变化后再更新。"},"10":{"id":"10","lesson":10,"prompt":"仓库报价只包含拣货打包，利润模型还要核对什么？","options":["尾程、附加费和退货费用","只核对商品颜色","无需再查，履约已全包"],"answer":0,"explanation":"“履约”这个词不保证报价包含全链路。要问清服务边界、计费重量和附加费。"},"11":{"id":"11","lesson":11,"prompt":"净收入已经扣了实际退款，接着又减相同退款金额，会发生什么？","options":["重复扣减，低估利润","更准确","提高利润"],"answer":0,"explanation":"同一笔损失只能计一次。未来退款预留与已发生退款应分开核算。"},"12":{"id":"12","lesson":12,"prompt":"100单中退了5单，能否认定收入减少5%？","options":["不能，需看退款金额与订单金额","能，都是5%","收入一定减少50%"],"answer":0,"explanation":"订单退款率是5%，但不同订单金额不同。计算收入影响需用实际退款金额。"},"13":{"id":"13","lesson":13,"prompt":"净收入50，商品及履约等非营销可变成本30，营销分摊15，订单贡献是多少？","options":["5","20","35"],"answer":0,"explanation":"50−30−15=5。这还不是公司净利润，也未代表现金已经到账。"},"14":{"id":"14","lesson":14,"prompt":"成本表里最有用的额外信息是什么？","options":["来源、口径和核对日期","更多颜色","把所有待补都写成0"],"answer":0,"explanation":"未知成本不等于零。来源和日期能帮助复核、更新并解释决策的不确定性。"},"15":{"id":"15","lesson":15,"prompt":"获客费1,000元，带来20位新客和10笔老客订单，CAC是多少？","options":["50元","约33元","100元"],"answer":0,"explanation":"1,000÷20=50元。30笔订单不能直接作为新客数。"},"16":{"id":"16","lesson":16,"prompt":"广告前贡献率20%，同口径ROAS为4，广告费占收入25%，结果如何？","options":["广告消耗超过广告前贡献","肯定赚钱，因为ROAS大于1","净利率是80%"],"answer":0,"explanation":"每100元收入广告前贡献20元，广告费25元，贡献为−5元。前提是收入、期间和归因口径可比。"},"17":{"id":"17","lesson":17,"prompt":"10,000次访问，订单转化率2%，客单价50元，收入是多少？","options":["10,000元","5,000元","100,000元"],"answer":0,"explanation":"10,000×2%=200单；200×50=10,000元。所有指标应对应同一期间与口径。"},"18":{"id":"18","lesson":18,"prompt":"目标收入10,000元、客单价50元，需要多少单？","options":["200单","500单","50单"],"answer":0,"explanation":"10,000÷50=200单。再结合访问量判断转化率目标是否合理。"},"19":{"id":"19","lesson":19,"prompt":"营销花费除以全部订单，得到的一定是CAC吗？","options":["不一定，它是每单营销分摊，需区分新客","一定是","一定是LTV"],"answer":0,"explanation":"CAC的分母是新客户；每单营销分摊的分母是订单。两者在全部为新客且一人一单时才可能相同。"},"20":{"id":"20","lesson":20,"prompt":"150单，每单广告前贡献20元，营销共2,000元，总贡献是多少？","options":["1,000元","3,000元","−2,000元"],"answer":0,"explanation":"150×20−2,000=1,000元。营销总额扣一次；不要再用CAC对全部订单重复扣费。"},"21":{"id":"21","lesson":21,"prompt":"流量持平、客单价持平、订单下降，最先关注什么？","options":["转化率以及漏斗环节","立刻全面加预算","直接归因于季节"],"answer":0,"explanation":"先定位变化发生在哪一层，再用细分数据核对原因。相关变化并不能自动证明因果。"},"22":{"id":"22","lesson":22,"prompt":"想用复购解释首单亏损，最有力的依据是？","options":["同批客户的实际复购贡献与回本周期","相信未来会复购","竞争对手在烧钱"],"answer":0,"explanation":"用同批客户的实际行为验证，不把远期预测当现金。收入LTV也不能直接等同可用于获客的利润。"},"23":{"id":"23","lesson":23,"prompt":"首单净收入50，非营销可变成本32，首单盈亏CAC是多少？","options":["18","32","50"],"answer":0,"explanation":"50−32=18。若要保留利润和安全余量，目标CAC应低于这个简化盈亏点。"},"24":{"id":"24","lesson":24,"prompt":"广告前贡献率25%，简化盈亏ROAS是多少？","options":["4","2.5","0.25"],"answer":0,"explanation":"1÷25%=4。每100元收入最多承担25元广告费，才在贡献层面刚好盈亏平衡。"},"25":{"id":"25","lesson":25,"prompt":"单笔贡献5元，其他不变，CAC增加3元后贡献是多少？","options":["2元","8元","5元"],"answer":0,"explanation":"获客成本增加会直接压缩贡献。分析还应考虑涨价、退款、汇率等可能一起变化。"},"26":{"id":"26","lesson":26,"prompt":"订单贡献为正，但库存先付款、货款后结算，可能出现什么？","options":["账面有贡献，现金仍紧张","现金一定充足","成本自动消失"],"answer":0,"explanation":"盈利和现金流的时间不同。增长预算还需覆盖库存和回款等待期。"},"27":{"id":"27","lesson":27,"prompt":"关键尾程成本未知时，最合理的结论是？","options":["先标待补并做成本区间分析","填0，直接决定放量","随便填一个当真实值"],"answer":0,"explanation":"可以用假设做情景练习，但真实决策必须保留缺口和条件，不能伪造精确性。"},"28":{"id":"28","lesson":28,"prompt":"哪句话更适合作为决策请求？","options":["请批准7天小额测试，上限1,000元，周五复盘","我们的数据很多","请领导关注一下"],"answer":0,"explanation":"明确预算、时限和验证安排，能让对方知道要决定什么、如何控制风险。"},"29":{"id":"29","lesson":29,"prompt":"修改成本后利润没有变化，首先检查什么？","options":["公式引用与输入是否正确连接","换一个表格颜色","增加销售目标"],"answer":0,"explanation":"可复用模型的结果必须随有效输入更新。零收入等边界也应有合理提示。"},"30":{"id":"30","lesson":30,"prompt":"净收入100，非广告可变成本65，广告费40，贡献与动作是什么？","options":["贡献−5，先定位成本与获客问题","贡献35，立即扩大广告","贡献60，继续放量"],"answer":0,"explanation":"100−65−40=−5。需要核对完整成本和数据质量，再决定调整或测试。"},"31":{"id":"31","lesson":31,"prompt":"资源有限的新项目，合理的渠道安排是？","options":["先明确主渠道与辅助渠道的任务","三个渠道同时最大投入","只按哪个平台热门决定"],"answer":0,"explanation":"选择要有用户与成本依据，并保留测试空间。渠道协同不意味着平均分配资源。"},"32":{"id":"32","lesson":32,"prompt":"加购稳定，支付完成突然下降，优先检查什么？","options":["支付报错、配送费用和结账流程","只增加博客数量","立刻重做所有图片"],"answer":0,"explanation":"最靠近掉点的环节应先排查，也要排除统计事件故障。"},"33":{"id":"33","lesson":33,"prompt":"按钮改色后销量上涨，就能确认颜色有效吗？","options":["不能，还需控制其他变化并验证","能，先后发生就是因果","所有按钮都应改成同色"],"answer":0,"explanation":"流量、活动和季节可能一起改变。尽可能采用合理对照和足够观察，不把相关性当因果。"},"34":{"id":"34","lesson":34,"prompt":"购后流程最应优先提供什么？","options":["订单与使用帮助，再安排适当复购内容","每天催促再买一次","隐藏退订入口"],"answer":0,"explanation":"先兑现体验和帮助使用，再判断复购时机。用户同意与沟通相关性都很重要。"},"35":{"id":"35","lesson":35,"prompt":"哪个改动有最明确的业务假设？","options":["提前说明运费，测试是否减少结账流失","统一把所有字放大","追逐最新设计风格"],"answer":0,"explanation":"这个假设说明用户顾虑、改动与待观察结果；仍需实际验证才能下结论。"},"36":{"id":"36","lesson":36,"prompt":"审计发现手机支付按钮失效和页脚间距不齐，先处理什么？","options":["支付按钮失效","页脚间距","同时重做整站"],"answer":0,"explanation":"影响核心购买流程的功能故障优先，完成后验证真实流程与关键设备。"},"37":{"id":"37","lesson":37,"prompt":"哪个结论最诚实也最有用？","options":["转化改善，但同期促销变化，因果待验证","这次改版肯定带来全部增长","数据不明显就删掉记录"],"answer":0,"explanation":"保留条件与不确定性有助于下次更好验证，也避免错误经验被当作固定方法。"},"38":{"id":"38","lesson":38,"prompt":"一个Listing销量下降，最合理的诊断是？","options":["分别看曝光、点击、转化及供货变化","肯定是标题字数少","保证提高出价就能恢复排名"],"answer":0,"explanation":"多个环节可能影响销量，平台排序机制也不是可用一句公式保证的结果。"},"39":{"id":"39","lesson":39,"prompt":"卖点优化最有价值的依据是？","options":["用户搜索意图、真实规格与常见顾虑","尽量堆满热门词","复制竞品全部承诺"],"answer":0,"explanation":"用户需要准确理解产品是否适合自己。不能凭文案创造不存在的功能。"},"40":{"id":"40","lesson":40,"prompt":"销量稳定但备货量远超需求，主要风险是什么？","options":["仓储费用和现金占用增加","一定降低所有成本","没有风险，库存越多越好"],"answer":0,"explanation":"库存要结合补货提前期与需求不确定性管理，过量备货会降低现金灵活性。"},"41":{"id":"41","lesson":41,"prompt":"广告花费200，归因销售额1,000，总销售额2,000，ACoS是多少？","options":["20%","10%","200%"],"answer":0,"explanation":"200÷1,000=20%；200÷2,000=10%是TACoS，回答的是另一类问题。"},"42":{"id":"42","lesson":42,"prompt":"使用FBA后，是否保证获得主报价位并盈利？","options":["不保证，还需考虑资格、竞争和成本","保证盈利","只要有库存就保证"],"answer":0,"explanation":"履约是竞争因素之一。主报价位资格与表现有条件，利润仍需要完整计算。"},"43":{"id":"43","lesson":43,"prompt":"200单总广告费1,000元，每单平均广告分摊是多少？","options":["5元","20元","1,000元"],"answer":0,"explanation":"1,000÷200=5元。这个结果是平均每单分摊，不是按新客数计算的CAC。"},"44":{"id":"44","lesson":44,"prompt":"哪项更支持先测试搜索型渠道？","options":["用户已有明确相关搜索需求","产品名字很新奇","团队刚学会拍视频"],"answer":0,"explanation":"主动搜索需求提供潜在购买意图，但还要核对竞争、价格与成本，不能据此保证成功。"},"45":{"id":"45","lesson":45,"prompt":"视频播放高但几乎没有商品点击，先检查什么？","options":["受众、产品关联性和行动引导","立刻加倍囤货","认定需求已经验证"],"answer":0,"explanation":"娱乐性或广泛传播不一定带来购买意图。先理解用户是否在内容中看见相关价值。"},"46":{"id":"46","lesson":46,"prompt":"哪种“证明”更可信？","options":["在可复现条件下演示真实效果","夸张写“全网第一”","省略不利条件"],"answer":0,"explanation":"清楚条件和限制的真实演示更有助于用户判断。未经证实的绝对化承诺会带来体验与规则风险。"},"47":{"id":"47","lesson":47,"prompt":"挑选达人最应同时考虑什么？","options":["受众匹配、内容质量与商业条件","只看粉丝最多","只看报价最低"],"answer":0,"explanation":"粉丝数量不能单独预测成交。要让合作对象、交付目标与利润空间匹配。"},"48":{"id":"48","lesson":48,"prompt":"收入50，落地成本15、履约6、平台费3、佣金8、售后预留2，广告前贡献是多少？","options":["16","24","35"],"answer":0,"explanation":"50−15−6−3−8−2=16。广告及其他未计费用仍需另行考虑。"},"49":{"id":"49","lesson":49,"prompt":"一条视频爆单但库存不足，首先应该怎么做？","options":["核对库存与交付承诺，调整销售并沟通","继续无限接单","只关注播放量"],"answer":0,"explanation":"保护客户体验需要真实库存和交付预期。爆量不能替代可履行的订单能力。"},"50":{"id":"50","lesson":50,"prompt":"产品评分最高，是否就应该直接大规模采购？","options":["不，应验证关键假设与成本","是，总分就是市场事实","只需再加一个评分维度"],"answer":0,"explanation":"分数常含主观判断。它能帮助优先测试，不能替代真实需求证据。"},"51":{"id":"51","lesson":51,"prompt":"用户先看演示，再去平台搜评价并购买，说明什么？","options":["渠道可能共同影响同一次购买","只有最后一个渠道有价值","应把所有平台归因销售额相加"],"answer":0,"explanation":"购买路径可能跨渠道。分配预算需要结合整体结果和增量证据，而不是简单归功于最后触点。"},"52":{"id":"52","lesson":52,"prompt":"团队每周只有5小时，渠道方案首先要考虑什么？","options":["执行资源与关键验证任务","把所有平台都列为重点","每天增加更多任务"],"answer":0,"explanation":"资源是策略的约束。集中有限时间测试关键假设，比无法落实的全渠道表更有用。"},"53":{"id":"53","lesson":53,"prompt":"标准替换滤芯已有明确型号搜索，初始测试可以优先考虑什么？","options":["相关搜索渠道，并核验成本竞争","只凭流行选择短视频","完全忽略型号匹配"],"answer":0,"explanation":"明确型号搜索提示主动意图。仍需要检查兼容信息、竞争、评价与利润。"},"54":{"id":"54","lesson":54,"prompt":"两个广告平台各认领同一笔100元订单，总真实销售额是多少？","options":["100元","200元","0元"],"answer":0,"explanation":"订单只发生一次。归因报告可以重叠，不能相加当作真实营收。"},"55":{"id":"55","lesson":55,"prompt":"多个渠道同时卖同一库存，怎样降低超卖？","options":["统一库存记录并考虑同步延迟与安全量","每个平台都填全部库存且不更新","只在月底对账"],"answer":0,"explanation":"可售库存应考虑已占用与处理中订单，定期核对同步异常。"},"56":{"id":"56","lesson":56,"prompt":"哪个渠道目标更可执行？","options":["测试搜索需求，观察贡献与转化，设预算上限","全面打造全域增长","所有指标都要最好"],"answer":0,"explanation":"具体目标能关联数据、成本和决策，也有助于团队对齐。"},"57":{"id":"57","lesson":57,"prompt":"渠道协同中最不应该忽略什么？","options":["一致的产品信息、库存与服务承诺","每个渠道用完全相反的规格","只统一配色即可"],"answer":0,"explanation":"用户跨渠道比较时，信息冲突会损害信任，也会造成售后和履约问题。"},"58":{"id":"58","lesson":58,"prompt":"一个好的渠道决策Memo应包含什么？","options":["方案理由、预算边界与验证条件","所有平台介绍的摘抄","只有一句“建议做TikTok”"],"answer":0,"explanation":"决策需要证据、代价和调整条件，不能只停留在平台偏好。"},"59":{"id":"59","lesson":59,"prompt":"哪一项能把渠道策略推进为执行？","options":["给关键任务分配负责人、截止日和验收标准","再增加十个平台名称","只写长期愿景"],"answer":0,"explanation":"清楚的责任与验收能减少等待和反复，让策略变成可以推进的项目。"},"60":{"id":"60","lesson":60,"prompt":"高播放、低成交、单位贡献为负时，合理选择是什么？","options":["限制投入并验证购买意图与经济模型","只要流量高就继续放量","改一下品牌名就放量"],"answer":0,"explanation":"曝光不是可持续增长的充分条件。先定位转化与成本问题，再决定是否继续。"},"61":{"id":"61","lesson":61,"prompt":"选择案例产品时，最有帮助的条件是？","options":["需求可研究、成本可核对、范围可控制","一定选择最热门且最贵的品","先投入大笔库存证明决心"],"answer":0,"explanation":"可验证与可完成优先。学习案例也应标明模拟内容，不能把假设当市场结论。"},"62":{"id":"62","lesson":62,"prompt":"哪种用户描述更能指导产品？","options":["短途旅行者希望在登机箱内快速分类衣物","25—35岁女性","所有互联网用户"],"answer":0,"explanation":"场景和任务更能推导功能、卖点与渠道。年龄标签本身不能说明购买原因。"},"63":{"id":"63","lesson":63,"prompt":"“视频很多点赞”能直接证明什么？","options":["内容有互动，付费需求仍需验证","产品一定畅销","目标定价已经被接受"],"answer":0,"explanation":"互动、意向和支付是不同强度的信号。证据应与要判断的问题匹配。"},"64":{"id":"64","lesson":64,"prompt":"发现一条差评就认定普遍痛点，主要问题是什么？","options":["样本不足，需看频次、场景与其他证据","差评不能阅读","必须复制竞品产品"],"answer":0,"explanation":"单条反馈是线索，不是普遍性的证明。注意样本偏差和评价真实性。"},"65":{"id":"65","lesson":65,"prompt":"哪条证据记录更完整？","options":["链接、日期、原始信息、判断与限制","一张无来源截图","一个忘记出处的数字"],"answer":0,"explanation":"可追溯记录允许复核，也能在信息过期或被反驳时更新结论。"},"66":{"id":"66","lesson":66,"prompt":"两类用户需求冲突时，初期更合理的做法是？","options":["选定核心人群并解释取舍","把所有功能都加上","写“适合所有人”"],"answer":0,"explanation":"有限资源需要明确服务对象。全覆盖往往让价值表达和产品成本失去重点。"},"67":{"id":"67","lesson":67,"prompt":"需求和定价还没验证，先做哪件事更合理？","options":["收集购买理由并做小范围价格验证","先定制豪华包装","先做一百页品牌手册"],"answer":0,"explanation":"优先解决会改变项目方向的未知。越早获得关键信息，越能减少无效投入。"},"68":{"id":"68","lesson":68,"prompt":"没有测试数据，可以写“耐用提升300%”吗？","options":["不可以，应使用有依据的具体描述","可以，文案需要冲击力","只要竞品也这么写就行"],"answer":0,"explanation":"数值承诺需要可核验依据。真实规格与实际演示比虚构优势更可靠。"},"69":{"id":"69","lesson":69,"prompt":"降价后销量增加，是否证明定价更好？","options":["不一定，需看总贡献与其他影响","一定，销量是唯一目标","一定更差"],"answer":0,"explanation":"低价可能牺牲每单贡献，也可能提升总贡献；需用同口径实际数据比较。"},"70":{"id":"70","lesson":70,"prompt":"供应商报价缺少运输条款，应该怎么处理？","options":["确认包含范围，并保留待补项","默认为到仓全包","把所有物流成本设为0"],"answer":0,"explanation":"报价边界不明时不能直接比较。确认交货地点、费用责任与计费条件。"},"71":{"id":"71","lesson":71,"prompt":"基准情景盈利，较差情景严重亏损，下一步是什么？","options":["验证关键假设并设置投入边界","忽略较差情景","只展示最好情景"],"answer":0,"explanation":"情景分析帮助暴露风险。可承受的投入和验证顺序应由风险共同决定。"},"72":{"id":"72","lesson":72,"prompt":"哪种表现更能证明理解CAC？","options":["能说明分子分母、期间及其决策用途","能背出三个字母","能找到一张好看的图"],"answer":0,"explanation":"能定义、计算并解释作用，比只记忆名称更接近可应用的理解。"},"73":{"id":"73","lesson":73,"prompt":"把最低成本、最高售价、最低CAC同时作为唯一预测，有什么问题？","options":["可能过度乐观，缺少压力情景","一定最准确","只要公式正确就没问题"],"answer":0,"explanation":"正确公式无法弥补偏乐观输入。需保留基准依据及下行情景。"},"74":{"id":"74","lesson":74,"prompt":"哪条风险描述最可执行？","options":["若交期延误超过7天，由采购负责人启动备选方案","可能有供应链问题","竞争激烈，需要努力"],"answer":0,"explanation":"明确触发条件、责任人和动作，才能在风险出现时快速响应。阈值需结合实际调整。"},"75":{"id":"75","lesson":75,"prompt":"上线计划为何要包含补货提前期？","options":["避免放量后断货并提前安排现金","让计划看起来更长","因为广告费会自动减少"],"answer":0,"explanation":"需求增长、采购和回款时间需协调。提前期会影响补货点与资金需求。"},"76":{"id":"76","lesson":76,"prompt":"同一轮同时改价格、受众、脚本与页面，主要难点是什么？","options":["难以判断哪个变化带来结果","肯定提升效率","一定获得更多成交"],"answer":0,"explanation":"多个变量同时变化会影响解释。探索时可广泛试，但归因结论要谨慎。"},"77":{"id":"77","lesson":77,"prompt":"手机上商品页很好看但无法选择规格，应该优先做什么？","options":["修复选择与购买流程","继续加大流量","增加首页动画"],"answer":0,"explanation":"核心任务可完成是体验基础。功能修复后再用真实设备确认。"},"78":{"id":"78","lesson":78,"prompt":"跨团队合作中，最能减少反复的做法是？","options":["共用产品事实、目标、负责人和验收标准","每人各写一套规格","只增加群聊消息"],"answer":0,"explanation":"统一事实与工作边界能减少误解。协作还需明确交接时间和遇到冲突的处理方式。"},"79":{"id":"79","lesson":79,"prompt":"展示客户案例时，最应遵循什么？","options":["仅使用必要信息并处理隐私与授权","公开所有邮箱证明真实","默认所有内部数据都能外发"],"answer":0,"explanation":"展示价值不需要暴露无关个人信息。使用数据前需核对授权与适用要求。"},"80":{"id":"80","lesson":80,"prompt":"收到声称平台客服的邮件索要验证码，应该怎么做？","options":["不提供，独立进入官方渠道核验","立即回复验证码","把密码一起发送"],"answer":0,"explanation":"验证码和密码不能交给来历不明的联系人。用已知官方入口核对账户状态。"},"81":{"id":"81","lesson":81,"prompt":"预算减半时最有用的管理动作是？","options":["重排优先级并明确暂停项和目标变化","要求所有任务照旧完成","平均砍掉每项的一半"],"answer":0,"explanation":"不同任务的必要性和信息价值不同。负责人需要做明确取舍并向相关方沟通。"},"82":{"id":"82","lesson":82,"prompt":"页面要等样品确认规格才能完成，计划里应该体现什么？","options":["样品确认是页面定稿的前置依赖","两项完全无关","让设计自行猜规格"],"answer":0,"explanation":"依赖关系决定排期和阻塞。先暴露等待点，再安排可并行的工作。"},"83":{"id":"83","lesson":83,"prompt":"退款率超预警线后，好的看板应帮助你做什么？","options":["定位商品与原因，明确负责人和处理动作","只把数字变红","继续追求更多曝光"],"answer":0,"explanation":"预警应连接调查与执行。阈值需适应样本规模、品类和时间窗。"},"84":{"id":"84","lesson":84,"prompt":"初期预算最合理的使用方式是？","options":["分阶段投入，按证据决定后续预算","一次性全部投出","每个渠道平均分，不再调整"],"answer":0,"explanation":"分阶段投入能在获得新信息后调整。投入规模需符合可承受损失与执行能力。"},"85":{"id":"85","lesson":85,"prompt":"只有10次访问、没有成交，能直接证明产品无需求吗？","options":["不能，样本与流量质量不足以支持结论","能，立刻判定失败","必须无限投钱直到成交"],"answer":0,"explanation":"停止规则应兼顾证据量、成本上限与风险，避免过早或无止境地测试。"},"86":{"id":"86","lesson":86,"prompt":"汇报时间突然减半，最该优先保留什么？","options":["核心结论、关键证据、风险与决策请求","所有术语定义","所有页面截图"],"answer":0,"explanation":"先服务听众的决定。细节可留在附件或后续提问中。"},"87":{"id":"87","lesson":87,"prompt":"哪种结构更适合管理者快速评估？","options":["建议与理由在前，后接证据和执行风险","先展示几十页资料再给结论","只放视觉图，不说明假设"],"answer":0,"explanation":"清楚的主张让读者知道如何理解后续证据，也方便检验逻辑。"},"88":{"id":"88","lesson":88,"prompt":"定稿前发现核心结论依赖未验证的假设，应该怎么做？","options":["明确标注并补验证计划，必要时调整结论","隐藏假设以显得自信","用更漂亮的排版遮盖"],"answer":0,"explanation":"让不确定性可见是负责任的判断。结论强度应与证据强度匹配。"},"89":{"id":"89","lesson":89,"prompt":"同事连续两次延迟交付，哪种反馈更有效？","options":["说明具体延误与影响，询问阻碍并约定改进","说“你就是不负责”","不说问题，只自己加班补上"],"answer":0,"explanation":"具体事实和影响更可讨论。听取背景后共同确定支持、责任与检查时间。"},"90":{"id":"90","lesson":90,"prompt":"下一阶段最有价值的目标是什么？","options":["负责一个有目标、协作和复盘的实际项目","只追求更多打卡数字","认为通关就已具备所有管理能力"],"answer":0,"explanation":"课程提供基础与练习；真实场景里的决策、反馈和结果能进一步检验并发展能力。"},"1b":{"id":"1b","lesson":1,"prompt":"GMV、Revenue和利润可以直接当作同一个数吗？","options":["不能，它们描述不同层面","可以，只是叫法不同","只要订单很多就可以"],"answer":0,"explanation":"交易规模、确认收入和扣成本后的利润各自回答不同问题。先明确口径，再比较。"},"extra1":{"id":"extra1","lesson":1,"prompt":"今天销售报告新增1,000元收入，能否确定银行账户今天也增加了1,000元？","options":["不能，到账还受结算时间、退款与手续费等影响","能，销售与收款永远同步","不能，因为收入永远不会到账"],"answer":0,"explanation":"销售确认与现金到账是不同事件。核对支付、结算与银行流水，才能知道实际收到了多少、何时收到。"},"extra2":{"id":"extra2","lesson":8,"prompt":"一件商品采购12美元，头程3美元、关税1美元，到仓成本16美元。销售模型中应扣多少到仓成本？","options":["28美元：16加采购12","16美元：采购已在合计里","12美元：物流不算成本"],"answer":1,"explanation":"12+3+1=16美元。成本可以拆开列，也可以列合计，但不能同时重复计入。"},"extra3":{"id":"extra3","lesson":15,"prompt":"营销花费2250美元，带来150笔订单，其中135位新客户。新客CAC与每单营销费用分别是多少？","options":["15美元；16.67美元","16.67美元；15美元","两项都是16.67美元"],"answer":1,"explanation":"2250÷135≈16.67美元/新客；2250÷150=15美元/单。用新客CAC乘所有订单会高估费用。"},"extra4":{"id":"extra4","lesson":17,"prompt":"100次会话中，5次会话发生购买，共产生6笔订单。按购买会话计算的转化率是多少？","options":["5%","6%","无法计算，因为订单数不是5"],"answer":0,"explanation":"购买会话5÷总会话100=5%。6÷100是订单/会话比，不能冒充同一个指标。"},"extra5":{"id":"extra5","lesson":22,"prompt":"一批客户180天内平均消费120元，除初次获客外的可变成本90元，CAC为25元。扣获客后平均还剩多少贡献？","options":["95元","30元","5元"],"answer":2,"explanation":"广告前贡献120−90=30元，再减CAC25元，剩5元。120元销售额不能直接当作可用于获客的预算。"},"extra6":{"id":"extra6","lesson":24,"prompt":"每100元销售额扣除除广告外的可变成本后剩25元。简化模型下盈亏ROAS是多少？","options":["2倍","4倍","25倍"],"answer":1,"explanation":"最多可花25元广告费，100÷25=4倍。若广告前贡献已经为零或负数，就没有正的首单广告预算空间。"},"extra7":{"id":"extra7","lesson":34,"prompt":"你拿到一份订单客户邮箱表，想发新品促销。第一步更合适的是？","options":["全部导入群发，买过就等于同意营销","先核对营销授权、退订状态和允许用途","换成个人邮箱发送以避开平台限制"],"answer":1,"explanation":"购买行为本身不能被当作所有后续用途的无限授权。先核对用途、同意、退出记录与适用要求，再设计营销。"},"extra8":{"id":"extra8","lesson":36,"prompt":"后台只有1笔订单，分析系统却记录了2次purchase，且transaction_id为空。最先做什么？","options":["立即加广告预算，转化变好了","先核查重复触发与交易ID，再用测试订单验收","把销售额直接除以2当作修复"],"answer":1,"explanation":"先修测量，再判断增长。凭感觉除以2不能解决重复计数，也会使不同订单更难核对。"},"extra9":{"id":"extra9","lesson":40,"prompt":"假设日均卖5件，补货提前期20天，安全库存30件，需求稳定。简单补货点是多少？","options":["100件","130件","30件"],"answer":1,"explanation":"5×20+30=130件。达到补货点时还要看在途库存与可用现金，不能只看仓库现货就机械下单。"},"extra10":{"id":"extra10","lesson":54,"prompt":"某广告报告归因100单，能直接说停止广告就会少100单吗？","options":["能，归因就是因果","不能，还需要合适的对照或增量证据","不能，因为所有归因数据都没用"],"answer":1,"explanation":"归因有助于优化与理解路径，但不能直接回答停投会少多少单。对照实验能提供更接近因果的问题答案。"},"extra11":{"id":"extra11","lesson":55,"prompt":"邮件说店铺一小时后停用，要求点击链接并回复两步验证代码。最佳动作是？","options":["先回复验证码，避免封店","从官方入口自行登录核实，并通过官方支持确认","转发给同事，让同事先试链接"],"answer":1,"explanation":"紧急口吻不能证明身份。验证码属于你的登录凭证，不应交给来信者；独立进入官方入口核实。"},"extra12":{"id":"extra12","lesson":73,"prompt":"你同时换了广告素材、降价20%并改投放人群，销量上涨。可以得出什么结论？","options":["新素材一定有效","降价一定是唯一原因","组合变化与销量上涨同时发生，还不能分清各自作用"],"answer":2,"explanation":"多个变量一起变化难以解释原因。下一轮收窄假设，在可比条件下测试，并同时看利润与售后。"},"extra13":{"id":"extra13","lesson":80,"prompt":"朋友说某品类佣金一直是15%，你准备在另一个国家站点上新。应该怎么做？","options":["把15%永久写入模型","核对目标站点和品类的现行官方规则，并记录核验日期","先忽略佣金，出了单再算"],"answer":1,"explanation":"费用和政策都有适用范围，也会变化。课程中的数字是练习假设，真实经营输入需来自当前可核对的资料。"},"extra14":{"id":"extra14","lesson":82,"prompt":"哪一种任务说明最容易执行和验收？","options":["尽快把页面做好看一点","小林周五18点前交移动端商品页；价格与配送信息清楚、购买按钮可用，周三看初稿","大家有空都优化一下页面"],"answer":1,"explanation":"第二项明确了人、时间、产出与验收。接下来还要确认对方理解一致、资源够用，而不是发完一句话就等待。"},"extra15":{"id":"extra15","lesson":89,"prompt":"同事交来的报告少了成本依据，哪种反馈更合适？","options":["你做事一直不认真","今天评审的报告里3项成本没有来源，所以我们无法判断利润；你卡在哪里，我们怎样补齐？","你不适合这份工作"],"answer":1,"explanation":"第二项具体描述可观察事实和影响，并打开解决问题的对话。它比指责人格更能促成下一步改进。"}},"chapters":[{"id":1,"title":"看懂一门生意","subtitle":"从销售额，到真正留下的利润","range":"01—30","outcome":"商品利润模型 · 经营判断","icon":"chart"},{"id":2,"title":"找到增长的路径","subtitle":"理解渠道，也理解用户的选择","range":"31—60","outcome":"渠道策略 · 网站诊断","icon":"compass"},{"id":3,"title":"像负责人一样思考","subtitle":"把知识串成一个完整商业方案","range":"61—90","outcome":"商业案例 · 项目推进 · 汇报","icon":"flag"}],"sources":[{"id":"shopify-sales","title":"Shopify：销售额、退款与收款口径","url":"https://help.shopify.com/en/manual/reports-and-analytics/shopify-reports/report-types/default-reports/sales-report","topic":"收入口径","lessonDays":[1,5,11,17,18,27,83],"checked":"2026-10-30","note":"已打开核验。重点看 Common sales report terms 与 Sales versus payments；销售报告不等于现金到账。英文，可用Safari翻译。"},{"id":"shopify-profit","title":"Shopify：看懂毛利报告","url":"https://help.shopify.com/en/manual/reports-and-analytics/shopify-reports/report-types/default-reports/profit-reports","topic":"成本与毛利","lessonDays":[2,3,4,6,13,29],"checked":"2026-10-30","note":"已打开核验。产品需在售出时已有成本记录；后台毛利不自动等于扣完广告、履约等费用后的净利润。"},{"id":"shopify-cro","title":"Shopify：转化率与页面优化入门","url":"https://www.shopify.com/blog/120261189-conversion-rate-optimization","topic":"转化率优化","lessonDays":[17,18,21,32,33,35,36,77],"checked":"2026-10-30","note":"已打开核验。只读转化率定义、摩擦与测试部分；不把文章里的行业均值当作所有店铺的达标线。"},{"id":"shopify-cohorts","title":"Shopify：按首购时间看客户复购","url":"https://help.shopify.com/en/manual/reports-and-analytics/shopify-reports/report-types/default-reports/customers-reports","topic":"复购与客户分组","lessonDays":[22,26,34,37,78],"checked":"2026-10-30","note":"已打开核验。重点看 Customer cohort analysis；预测消费额是预测，不是已实现利润。"},{"id":"ga4-ecommerce","title":"Google Analytics：商品、购买与退款事件","url":"https://developers.google.com/analytics/devguides/collection/ga4/ecommerce?client_type=gtag&hl=en","topic":"数据质量","lessonDays":[20,32,36,54,83],"checked":"2026-10-30","note":"已打开核验。面向开发的官方文档，选读购买/退款与transaction_id；学习重点是向技术同事提出正确验收要求，无需背代码。"},{"id":"google-attribution","title":"Google Ads：归因模型如何分配功劳","url":"https://support.google.com/google-ads/answer/6259715/about-attribution-models?hl=en-GB","topic":"归因","lessonDays":[16,19,24,54,56,83],"checked":"2026-10-30","note":"已打开核验。理解模型、归因窗口与可参与归因渠道；不同报表口径不能直接相加。"},{"id":"google-lift","title":"Google Ads：归因订单与增量订单的区别","url":"https://support.google.com/google-ads/answer/14102450?hl=en","topic":"因果与增量","lessonDays":[54,58,73,84,85],"checked":"2026-10-30","note":"已打开核验。重点看 attributed conversions 与 incremental conversions；工具可用性因账户而异，课程只要求掌握对照思路。"},{"id":"amazon-pricing","title":"Amazon美国站：费用与收入计算器","url":"https://sell.amazon.com/pricing","topic":"平台费用","lessonDays":[9,40,43,70,75],"checked":"2026-10-30","note":"已打开核验。用于查费用类别和进入Revenue Calculator；费率取决于站点、品类、尺寸、时间，不把示例15%写成统一规则。"},{"id":"amazon-inventory","title":"Amazon：库存与补货点入门","url":"https://sell.amazon.com/blog/ecommerce-inventory-management?mons_sel_locale=en_US","topic":"库存与资金","lessonDays":[40,55,75,80,82,84],"checked":"2026-10-30","note":"已打开核验。补货点=日均需求×补货提前期+安全库存；实务还要看在途、已分配库存、季节变化与资金。"},{"id":"tiktok-shoppable","title":"TikTok Shop Academy：可购物视频入门","url":"https://seller-us.tiktok.com/university/course?content_id=2520930699921198&learning_id=2520930700379950","topic":"内容电商","lessonDays":[45,47,49,50,51,76],"checked":"2026-10-30","note":"已打开核验，页面含视频课程介绍与文字内容。美国站资料，视频可能受地区或登录条件影响；不作为通关必需。"},{"id":"tiktok-creative","title":"TikTok：开场、主体与行动提示","url":"https://ads.tiktok.com/business/en/blog/creative-best-practices-top-performing-ads?acq_banner_version=73412989","topic":"创意结构","lessonDays":[46,47,50,68,76],"checked":"2026-10-30","note":"已打开核验。选读Hook、Body、Close；把创意原则当待测试假设，不照搬案例提升比例。"},{"id":"shopify-phishing","title":"Shopify：识别钓鱼与保护账号","url":"https://help.shopify.com/en/manual/privacy-and-security/account-security/phishing","topic":"账号安全","lessonDays":[31,55,65,79,80],"checked":"2026-10-30","note":"已打开核验。通过自己保存的官方入口核实消息；不向来信者提供密码、验证码或恢复码。"},{"id":"shopify-privacy","title":"Shopify：客户隐私设置与同意选择","url":"https://help.shopify.com/en/manual/privacy-and-security/privacy/customer-privacy-settings/privacy-settings","topic":"数据使用与隐私","lessonDays":[34,36,37,77,78,80],"checked":"2026-10-30","note":"已打开核验。隐私设置要匹配实际数据用途和第三方服务；自动模板不代表所有市场和业务都已合规。"},{"id":"ccl-feedback","title":"CCL：用情境、行为与影响给反馈","url":"https://www.ccl.org/articles/leading-effectively-article/closing-the-gap-between-intent-vs-impact-sbii/?trk=article-ssr-frontend-pulse_little-text-block","topic":"管理反馈","lessonDays":[28,58,82,86,89,90],"checked":"2026-10-30","note":"已打开核验。SBI后询问对方意图与困难；课程用原创工作场景练习，不评价人格。"},{"id":"ifrs-inventory","title":"IFRS：存货成本的边界","url":"https://www.ifrs.org/issued-standards/list-of-standards/ias-2-inventories/","topic":"成本口径","lessonDays":[2,4,5,8,13,29,70,71],"checked":"2026-10-30","note":"已打开核验。选读About：存货成本包括采购、加工及使存货到达当前地点和状态的其他成本。课程简化模型须标明口径。"},{"id":"ifrs-principal-agent","title":"IFRS教学材料：卖商品与代为撮合的收入","url":"https://www.ifrs.org/content/dam/ifrs/supporting-implementation/smes/2026-webcasts/revised-section-23-revenue-from-contracts-with-customers-part-2.pdf","topic":"收入确认基础","lessonDays":[1,5,30],"checked":"2026-10-30","note":"已打开核验，19页PDF。选读第11页Principal versus agent的总额/净额对照；作为概念拓展，不要求通读或据此处理真实报税。"},{"id":"google-experiments","title":"Google Ads：如何做有清晰假设的实验","url":"https://support.google.com/google-ads/answer/7281575/test-with-confidence-in-google-ads-google-best-practices","topic":"实验设计","lessonDays":[25,33,36,63,67,73,81,85],"checked":"2026-10-30","note":"已打开核验。先写假设、一次比较一个变量，并提前确定成功指标；前后两天的变化不能自动证明因果。"},{"id":"amazon-acos","title":"Amazon Ads：ACoS与ROAS怎么算","url":"https://advertising.amazon.com/library/guides/acos-advertising-cost-of-sales","topic":"广告效率","lessonDays":[16,19,24,41,42,43,75,83],"checked":"2026-10-30","note":"已打开核验。只有相同广告花费、归因销售额与时间口径下，ACoS和ROAS才互为倒数；销售回报不是净利润率。"}],"glossary":[{"term":"GMV vs Revenue","meaning":"GMV描述交易规模，Revenue描述按明确口径确认的收入，利润还要扣成本。先问“谁的收入、包含什么、哪段时间”，再比较数字。","day":1},{"term":"COGS","meaning":"COGS是已售商品对应的成本。采购、包装和入库相关费用的归集要有一致口径。广告费要另列；已计入COGS的头程不能再扣一次。","day":2},{"term":"Gross Profit / Gross Margin","meaning":"毛利=净销售收入−已售商品成本；毛利率=毛利÷净销售收入。它是利润的一层，不能代替扣除营销等费用后的结果。","day":3},{"term":"SKU毛利练习","meaning":"把收入、成本与期间写在一起。先算对，再说明这个结果还没包含哪些费用。缺数据时可以用明确标注的假设练习。","day":4},{"term":"Landed Cost","meaning":"Landed Cost是把货送达约定地点的完整落地成本。明确地点、数量与包含项；摊分采购、包装、头程、关税与入库，避免漏项或重复。","day":8},{"term":"平台费 / 支付费","meaning":"不同渠道的费用结构不同。按市场、类目、尺寸和服务读取当前官方费用；比例费、固定费和退款后处理规则要分清。","day":9},{"term":"履约 / 尾程","meaning":"履约包括拣货、打包、包材、出库与尾程，另有尺寸、偏远地区和逆向物流等可能费用。按实际计费单位摊到订单。","day":10},{"term":"退款与损耗","meaning":"退款会减少收入，也可能带来回收商品、逆向运费和不可退手续费。订单退款率与金额退款率分开；已扣的退款不要再全额预留。","day":11},{"term":"CAC","meaning":"CAC=获客相关投入÷新增客户数。渠道CAC、整体CAC、付费CAC各有口径。订单数含复购时，不能直接代替新增客户数。","day":15},{"term":"ROAS / MER","meaning":"ROAS看广告归因收入÷广告支出；本课程MER指总净收入÷总营销投入。它们需配合利润、退款和归因口径一起判断。","day":16},{"term":"AOV / CVR","meaning":"同口径下：订单数=访问次数×订单转化率，收入=订单数×客单价。平台也可能按转化会话计算CVR，使用前要确认定义。","day":17},{"term":"漏斗计算","meaning":"收入目标可以拆成访问、转化率和客单价。但目标不是预测；每个提升假设都需要有具体动作和可验证依据。","day":18},{"term":"LTV / Retention","meaning":"LTV可以是收入口径或贡献口径，必须写清。判断能承受多少CAC时，更适合看分客户群、固定时间窗的贡献价值和回本时间。","day":22},{"term":"Break-even CAC","meaning":"在一位新客一笔首单的简化模型里，首单广告前贡献就是首单盈亏CAC。目标CAC还应为固定费用、波动和利润留出空间。","day":23},{"term":"Break-even ROAS","meaning":"同收入与费用口径下，盈亏ROAS=1÷广告前贡献率。公式不解决归因偏差，也不覆盖固定费用。","day":24},{"term":"敏感性分析","meaning":"敏感性分析先一次改变一个变量，其余保持一致，再做组合压力情景。把结果变成动作：优先验证最不确定、影响最大的假设。","day":25},{"term":"渠道角色","meaning":"渠道选择看用户如何发现、比较和购买，以及经济模型与执行能力。平台角色是思考起点，不是适用于所有商品的定律。","day":31},{"term":"Shopify漏斗","meaning":"访问—商品浏览—加购—结账—购买—复购，每一步都回答不同问题。先核验事件，再按设备与流量来源查掉点。","day":32},{"term":"CRO","meaning":"CRO围绕用户障碍：看不懂产品、不信任、怕买错、费用意外、操作困难。用明确假设、小范围改动和守护指标验证。","day":33},{"term":"CRM / Retention","meaning":"欢迎、弃购和购后三类沟通对应不同问题。遵守用户授权和适用规则，提供退订、控制频次，不对已购买用户发送冲突信息。","day":34},{"term":"Marketplace机制","meaning":"平台集中需求、信任与履约服务，同时带来规则、费用和竞争。理解曝光—点击—转化，别把排名变化简化为单一因素。","day":38},{"term":"Listing / Ranking","meaning":"相关关键词帮助匹配意图；图片、功能、规格、评价和配送信息帮助判断。内容需真实一致，避免夸大和关键词堆砌。","day":39},{"term":"FBA / Fees","meaning":"FBA提供履约服务，商家仍要管理库存、补货、退货与利润。费用随市场、尺寸、类目和时间变化，使用当前官方估算。","day":40},{"term":"PPC基础","meaning":"ACoS=广告花费÷广告归因销售额；TACoS=广告花费÷总销售额。注意收入、期间和广告类型一致，并结合贡献空间。","day":41},{"term":"内容电商模型","meaning":"有效内容把场景、痛点、演示、证据和下一步连接起来。播放量只代表触达的一部分，需观察点击、成交和退货。","day":45},{"term":"Creative / Content","meaning":"从开头如何抓住注意、演示如何证明、结尾如何引导三个部分拆解。把事实证据与创意表达分开，保持产品承诺真实。","day":46},{"term":"Creator / Affiliate","meaning":"先定义目标用户和内容任务，再明确寄样、佣金、交付、使用权与披露要求。先做小样本合作，观察内容与成交质量。","day":47},{"term":"履约与利润","meaning":"按订单去重核算平台费、达人佣金、广告、履约和售后。样品、内容制作等投入也需进入总体项目预算。","day":48},{"term":"Channel Strategy","meaning":"用户在哪里发现问题、如何比较、为何信任、费用能否覆盖、团队能否执行。每个答案都要影响优先级或测试计划。","day":52},{"term":"Product-Channel Fit","meaning":"把购买意图、演示需求、价格与履约放在同一框架。给出初始主渠道，再明确什么结果会让你调整选择。","day":53},{"term":"Attribution基础","meaning":"归因分配“功劳”，增量分析问“没有这个动作会怎样”。平台窗口不同可能认领同一订单；先去重，再看整体经营与实验。","day":54},{"term":"库存 / 价格一致性","meaning":"建立可追溯的库存主记录，考虑占用、退货与同步延迟。自营渠道促销需协调，涉及第三方转售定价不能套用通用强制最低价。","day":55},{"term":"选品","meaning":"选一个你能理解、资料可获得的普通商品。明确这一轮是学习与验证项目，用小范围研究检验假设，不急于采购和上线。","day":61},{"term":"用户问题","meaning":"用情境、任务、困难和替代方案描写用户。人口标签只提供部分背景，真正的购买动机要从行为和问题里找。","day":62},{"term":"用户细分","meaning":"不同群体可能有不同任务、预算与替代品。先选择一个核心细分，用其需求决定产品取舍，再考虑扩展。","day":66}]};
